#!/usr/bin/env python3
from __future__ import annotations
from pathlib import Path
import base64
import hashlib
import json
import sys
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

ROOT = Path(__file__).resolve().parent
RECORD = ROOT / "SOVEREIGN_LOCK_RECORD.json"

def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()

def merkle_root(hex_digests):
    if not hex_digests:
        return hashlib.sha256(b"").hexdigest()
    level = [bytes.fromhex(x) for x in hex_digests]
    while len(level) > 1:
        if len(level) % 2:
            level.append(level[-1])
        level = [
            hashlib.sha256(level[i] + level[i + 1]).digest()
            for i in range(0, len(level), 2)
        ]
    return level[0].hex()

def main() -> int:
    record = json.loads(RECORD.read_text(encoding="utf-8"))
    sig = record.pop("release_signature")
    failures = []

    for item in record["files"]:
        path = ROOT / item["path"]
        if not path.is_file():
            failures.append(f"MISSING {item['path']}")
            continue
        actual_size = path.stat().st_size
        actual_hash = sha256_file(path)
        if actual_size != item["bytes"]:
            failures.append(f"SIZE {item['path']}: {actual_size} != {item['bytes']}")
        if actual_hash != item["sha256"]:
            failures.append(f"HASH {item['path']}: {actual_hash} != {item['sha256']}")

    computed_root = merkle_root([x["sha256"] for x in record["files"]])
    if computed_root != record["merkle_root"]:
        failures.append(f"MERKLE {computed_root} != {record['merkle_root']}")

    canonical = json.dumps(
        record, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")
    public = Ed25519PublicKey.from_public_bytes(
        base64.b64decode(sig["public_key_raw_base64"])
    )
    try:
        public.verify(base64.b64decode(sig["signature_base64"]), canonical)
    except Exception as exc:
        failures.append(f"SIGNATURE {exc}")

    if failures:
        print("SOVEREIGN LOCK VERIFICATION: FAIL")
        for failure in failures:
            print(" -", failure)
        return 1

    print("SOVEREIGN LOCK VERIFICATION: PASS")
    print("Lock ID:", record["lock_id"])
    print("Files:", len(record["files"]))
    print("Bytes:", record["included_bytes"])
    print("Merkle root:", record["merkle_root"])
    print("Signature fingerprint:", sig["public_key_sha256_fingerprint"])
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""
Hybrid Lattice × Drive Residual-Honest Operator — Hardened V2
=============================================================

A standard-library reference implementation of the explicit invariants in
HYBRID_Lattice_x_Drive_Operator.md.

Implemented controls
--------------------
* finite exact-decimal validation (NaN and infinities refused)
* exactly three unique, same-unit primary measurements
* claimed <= measured usable interior
* append-only non-negative residual buckets
* residual == 0 gate for COMMIT
* evidence-label solvency
* explicit refusal boundaries
* zero-action SILENCE state
* atomic cycle numbering under concurrency
* HMAC-derived non-repeating neutral offsets
* SHA-256 chained ledger
* semantic replay verification, not hash-only verification
* HMAC-authenticated export manifest
* atomic state export
* Reed–Solomon erasure recovery over GF(256), or explicit refusal

Boundary
--------
This is a governance/accounting reference implementation. It does not establish
experimental physics, consciousness, legal personhood, or autonomous authority.
"""

from __future__ import annotations

import base64
import copy
import hashlib
import hmac
import json
import math
import os
import random
import re
import tempfile
import threading
from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation
from enum import Enum
from pathlib import Path
from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple

ZERO = Decimal("0")
SHA256_RE = re.compile(r"^[0-9a-f]{64}$")


def D(value: Any) -> Decimal:
    """Convert to an exact finite Decimal, rejecting booleans and non-finite data."""
    if isinstance(value, bool):
        raise ValueError("Boolean values are not valid decimals")
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError) as exc:
        raise ValueError(f"Invalid decimal value: {value!r}") from exc
    if not result.is_finite():
        raise ValueError(f"Non-finite decimal value refused: {value!r}")
    return ZERO if result == ZERO else result


def require_text(value: Any, name: str, *, allow_empty: bool = False) -> str:
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a string")
    text = value.strip()
    if not allow_empty and not text:
        raise ValueError(f"{name} cannot be empty")
    return text


def canonical_json(value: Any) -> str:
    """Stable JSON representation for hashes and HMACs."""
    def normalize(obj: Any) -> Any:
        if isinstance(obj, Decimal):
            return "0" if obj == ZERO else format(obj, "f")
        if isinstance(obj, Enum):
            return obj.value
        if isinstance(obj, dict):
            return {
                str(k): normalize(v)
                for k, v in sorted(obj.items(), key=lambda kv: str(kv[0]))
            }
        if isinstance(obj, (list, tuple)):
            return [normalize(v) for v in obj]
        if isinstance(obj, bytes):
            return base64.b64encode(obj).decode("ascii")
        if isinstance(obj, float) and not math.isfinite(obj):
            raise ValueError("Non-finite float cannot be canonicalized")
        return obj

    return json.dumps(
        normalize(value), sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


class Decision(str, Enum):
    COMMIT = "COMMIT"
    REFUSE = "REFUSE"
    SILENCE = "SILENCE"


class EvidenceKind(str, Enum):
    MEASUREMENT = "measurement"
    INFERENCE = "inference"
    PROOF = "proof"
    POLICY = "policy"
    NONE = "none"


def coerce_evidence(value: Any) -> EvidenceKind:
    if isinstance(value, EvidenceKind):
        return value
    try:
        return EvidenceKind(str(value))
    except ValueError as exc:
        raise ValueError(f"Unknown evidence kind: {value!r}") from exc


@dataclass(frozen=True)
class PrimaryMeasurement:
    name: str
    measured: Decimal
    usable: Decimal
    unit: str

    @classmethod
    def make(
        cls,
        name: str,
        measured: Any,
        usable: Optional[Any] = None,
        unit: str = "normalized-unit",
    ) -> "PrimaryMeasurement":
        name_t = require_text(name, "measurement name")
        unit_t = require_text(unit, "measurement unit")
        measured_d = D(measured)
        usable_d = measured_d if usable is None else D(usable)
        if measured_d < ZERO:
            raise ValueError(f"{name_t}: measured value cannot be negative")
        if usable_d < ZERO:
            raise ValueError(f"{name_t}: usable value cannot be negative")
        if usable_d > measured_d:
            raise ValueError(f"{name_t}: usable value cannot exceed measured value")
        return cls(name=name_t, measured=measured_d, usable=usable_d, unit=unit_t)


@dataclass(frozen=True)
class ResidualEvent:
    sequence: int
    bucket: str
    delta: Decimal
    balance_after: Decimal
    unit: str
    note: str


@dataclass(frozen=True)
class CycleResult:
    cycle: int
    decision: Decision
    reason: str
    claimed: Decimal
    interior: Decimal
    unit: str
    residual: Decimal
    offset: Tuple[int, int, int]
    offset_tag: str
    ledger_hash: str


@dataclass
class ResidualHonestOperatorV2:
    hmac_key: bytes
    source_sha256: str
    residual_unit: str = "normalized-residual"
    residual_events: List[ResidualEvent] = field(default_factory=list)
    ledger: List[Dict[str, Any]] = field(default_factory=list)
    counter: int = 0
    _lock: threading.RLock = field(default_factory=threading.RLock, repr=False)

    def __post_init__(self) -> None:
        if not isinstance(self.hmac_key, (bytes, bytearray)) or len(self.hmac_key) < 32:
            raise ValueError("hmac_key must be at least 32 bytes")
        self.hmac_key = bytes(self.hmac_key)
        self.source_sha256 = str(self.source_sha256).lower()
        if not SHA256_RE.fullmatch(self.source_sha256):
            raise ValueError("source_sha256 must be a valid lowercase SHA-256 digest")
        self.residual_unit = require_text(self.residual_unit, "residual_unit")

    def residual_balance(self, bucket: Optional[str] = None) -> Decimal:
        total = ZERO
        for event in self.residual_events:
            if bucket is None or event.bucket == bucket:
                total += event.delta
        return ZERO if total == ZERO else total

    def residual_buckets(self) -> Dict[str, Decimal]:
        balances: Dict[str, Decimal] = {}
        for event in self.residual_events:
            balances[event.bucket] = balances.get(event.bucket, ZERO) + event.delta
        return {k: (ZERO if v == ZERO else v) for k, v in balances.items()}

    def append_residual(self, bucket: str, delta: Any, note: str) -> ResidualEvent:
        bucket_t = require_text(bucket, "residual bucket")
        note_t = require_text(note, "residual note")
        delta_d = D(delta)
        with self._lock:
            before = self.residual_balance(bucket_t)
            after = before + delta_d
            if after < ZERO:
                raise ValueError(
                    f"Residual bucket {bucket_t!r} would become negative: "
                    f"{before} + ({delta_d}) = {after}"
                )
            after = ZERO if after == ZERO else after
            event = ResidualEvent(
                sequence=len(self.residual_events) + 1,
                bucket=bucket_t,
                delta=delta_d,
                balance_after=after,
                unit=self.residual_unit,
                note=note_t,
            )
            self.residual_events.append(event)
            self._append_ledger_locked(
                "RESIDUAL",
                {
                    "sequence": event.sequence,
                    "bucket": event.bucket,
                    "delta": event.delta,
                    "balance_after": event.balance_after,
                    "unit": event.unit,
                    "note": event.note,
                },
            )
            return event

    @staticmethod
    def usable_interior(
        primaries: Iterable[PrimaryMeasurement],
    ) -> Tuple[Decimal, str, List[PrimaryMeasurement]]:
        values = list(primaries)
        if len(values) != 3:
            raise ValueError("Exactly three primary measurements are required")
        if not all(isinstance(p, PrimaryMeasurement) for p in values):
            raise ValueError("All primaries must be PrimaryMeasurement instances")
        names = [p.name for p in values]
        if len(set(names)) != 3:
            raise ValueError("Primary measurement names must be unique")
        units = {p.unit for p in values}
        if len(units) != 1:
            raise ValueError("Primary measurements must use the same unit")
        interior = sum((p.usable for p in values), ZERO)
        return (ZERO if interior == ZERO else interior, values[0].unit, values)

    @staticmethod
    def _evidence_is_solvent(actual: EvidenceKind, presented_as: EvidenceKind) -> bool:
        if actual == EvidenceKind.NONE:
            return presented_as == EvidenceKind.NONE
        return actual == presented_as

    @classmethod
    def decide_state(cls, state: Mapping[str, Any]) -> Tuple[Decision, str]:
        claimed = D(state["claimed"])
        interior = D(state["interior"])
        residual = D(state["residual"])
        action = require_text(state["action"], "action", allow_empty=True)
        actual = coerce_evidence(state["actual_evidence"])
        presented = coerce_evidence(state["presented_as"])

        if bool(state["asserts_experimental_physics"]):
            return Decision.REFUSE, "experimental-physics claim exceeds documented boundary"
        if bool(state["asserts_legal_personhood"]):
            return Decision.REFUSE, "legal-personhood claim exceeds documented boundary"
        if bool(state["asserts_autonomous_authority"]):
            return Decision.REFUSE, "autonomous-authority claim exceeds documented boundary"
        if not cls._evidence_is_solvent(actual, presented):
            return Decision.REFUSE, "evidence label mismatch"
        if state["claim_unit"] != state["interior_unit"]:
            return Decision.REFUSE, "claim unit does not match measured interior unit"
        if claimed > interior:
            return Decision.REFUSE, "claimed exceeds measured usable interior"
        if residual != ZERO:
            return Decision.REFUSE, "unresolved residual blocks commit"
        if claimed == ZERO and not action:
            return Decision.SILENCE, "zero residual and no necessary action"
        return Decision.COMMIT, "all explicit solvency gates passed"

    def _offset_for(self, cycle: int, state: Mapping[str, Any]) -> Tuple[Tuple[int, int, int], str]:
        message = canonical_json(
            {
                "source_sha256": self.source_sha256,
                "cycle": cycle,
                "state": dict(state),
            }
        ).encode("utf-8")
        digest = hmac.new(self.hmac_key, message, hashlib.sha256).digest()
        x = int.from_bytes(digest[0:4], "big") % 2_000_001 - 1_000_000
        y = int.from_bytes(digest[4:8], "big") % 2_000_001 - 1_000_000
        z = -(x + y)
        return (x, y, z), digest.hex()

    def evaluate(
        self,
        *,
        primaries: Iterable[PrimaryMeasurement],
        claimed: Any,
        action: str,
        claim_unit: Optional[str] = None,
        actual_evidence: EvidenceKind = EvidenceKind.NONE,
        presented_as: EvidenceKind = EvidenceKind.NONE,
        asserts_experimental_physics: bool = False,
        asserts_legal_personhood: bool = False,
        asserts_autonomous_authority: bool = False,
    ) -> CycleResult:
        interior, interior_unit, primary_list = self.usable_interior(primaries)
        claimed_d = D(claimed)
        if claimed_d < ZERO:
            raise ValueError("claimed cannot be negative")
        action_t = require_text(action, "action", allow_empty=True)
        claim_unit_t = interior_unit if claim_unit is None else require_text(claim_unit, "claim_unit")
        actual = coerce_evidence(actual_evidence)
        presented = coerce_evidence(presented_as)
        for flag_name, flag_value in (
            ("asserts_experimental_physics", asserts_experimental_physics),
            ("asserts_legal_personhood", asserts_legal_personhood),
            ("asserts_autonomous_authority", asserts_autonomous_authority),
        ):
            if not isinstance(flag_value, bool):
                raise ValueError(f"{flag_name} must be a boolean")

        with self._lock:
            residual = self.residual_balance()
            state: Dict[str, Any] = {
                "primaries": [
                    {
                        "name": p.name,
                        "measured": p.measured,
                        "usable": p.usable,
                        "unit": p.unit,
                    }
                    for p in primary_list
                ],
                "claimed": claimed_d,
                "claim_unit": claim_unit_t,
                "interior": interior,
                "interior_unit": interior_unit,
                "residual": residual,
                "residual_unit": self.residual_unit,
                "action": action_t,
                "actual_evidence": actual,
                "presented_as": presented,
                "asserts_experimental_physics": asserts_experimental_physics,
                "asserts_legal_personhood": asserts_legal_personhood,
                "asserts_autonomous_authority": asserts_autonomous_authority,
            }
            decision, reason = self.decide_state(state)
            self.counter += 1
            cycle = self.counter
            offset, offset_tag = self._offset_for(cycle, state)
            if sum(offset) != 0:
                raise RuntimeError("neutral-offset invariant failed")

            payload = {
                "cycle": cycle,
                "state": state,
                "decision": decision,
                "reason": reason,
                "offset": offset,
                "offset_tag": offset_tag,
                "residual_buckets": self.residual_buckets(),
            }
            ledger_hash = self._append_ledger_locked("CYCLE", payload)

        return CycleResult(
            cycle=cycle,
            decision=decision,
            reason=reason,
            claimed=claimed_d,
            interior=interior,
            unit=interior_unit,
            residual=residual,
            offset=offset,
            offset_tag=offset_tag,
            ledger_hash=ledger_hash,
        )

    def _append_ledger_locked(self, event_type: str, payload: Mapping[str, Any]) -> str:
        event_type_t = require_text(event_type, "event_type")
        previous_hash = self.ledger[-1]["entry_hash"] if self.ledger else "0" * 64
        frozen_payload = json.loads(canonical_json(dict(payload)))
        body = {
            "index": len(self.ledger),
            "event_type": event_type_t,
            "previous_hash": previous_hash,
            "payload": frozen_payload,
        }
        entry_hash = sha256_hex(canonical_json(body).encode("utf-8"))
        self.ledger.append({**body, "entry_hash": entry_hash})
        return entry_hash

    @staticmethod
    def verify_hash_chain(entries: Sequence[Mapping[str, Any]]) -> Tuple[bool, Optional[int], str]:
        previous_hash = "0" * 64
        for index, entry in enumerate(entries):
            if entry.get("index") != index:
                return False, index, "index mismatch"
            if entry.get("previous_hash") != previous_hash:
                return False, index, "previous-hash mismatch"
            body = {
                "index": entry.get("index"),
                "event_type": entry.get("event_type"),
                "previous_hash": entry.get("previous_hash"),
                "payload": entry.get("payload"),
            }
            expected = sha256_hex(canonical_json(body).encode("utf-8"))
            if not hmac.compare_digest(str(entry.get("entry_hash", "")), expected):
                return False, index, "entry-hash mismatch"
            previous_hash = expected
        return True, None, "ok"

    def verify_semantics(
        self, entries: Optional[Sequence[Mapping[str, Any]]] = None
    ) -> Tuple[bool, Optional[int], str]:
        data = list(self.ledger if entries is None else entries)
        balances: Dict[str, Decimal] = {}
        residual_sequence = 0
        expected_cycle = 0
        seen_tags: set[str] = set()

        for index, entry in enumerate(data):
            event_type = entry.get("event_type")
            payload = entry.get("payload")
            if not isinstance(payload, dict):
                return False, index, "payload is not an object"
            try:
                if event_type == "RESIDUAL":
                    residual_sequence += 1
                    if payload.get("sequence") != residual_sequence:
                        return False, index, "residual sequence mismatch"
                    bucket = require_text(payload.get("bucket"), "bucket")
                    require_text(payload.get("note"), "note")
                    if payload.get("unit") != self.residual_unit:
                        return False, index, "residual unit mismatch"
                    delta = D(payload.get("delta"))
                    after = balances.get(bucket, ZERO) + delta
                    if after < ZERO:
                        return False, index, "negative residual balance"
                    after = ZERO if after == ZERO else after
                    if D(payload.get("balance_after")) != after:
                        return False, index, "residual balance_after mismatch"
                    balances[bucket] = after

                elif event_type == "CYCLE":
                    expected_cycle += 1
                    if payload.get("cycle") != expected_cycle:
                        return False, index, "cycle sequence mismatch"
                    state = payload.get("state")
                    if not isinstance(state, dict):
                        return False, index, "cycle state missing"
                    primaries_raw = state.get("primaries")
                    if not isinstance(primaries_raw, list):
                        return False, index, "primary list missing"
                    primaries = [
                        PrimaryMeasurement.make(
                            p["name"], p["measured"], p["usable"], p["unit"]
                        )
                        for p in primaries_raw
                    ]
                    interior, unit, _ = self.usable_interior(primaries)
                    if D(state.get("interior")) != interior:
                        return False, index, "interior recomputation mismatch"
                    if state.get("interior_unit") != unit:
                        return False, index, "interior unit mismatch"
                    residual_total = sum(balances.values(), ZERO)
                    residual_total = ZERO if residual_total == ZERO else residual_total
                    if D(state.get("residual")) != residual_total:
                        return False, index, "residual snapshot mismatch"
                    expected_buckets = {
                        k: ("0" if v == ZERO else format(v, "f"))
                        for k, v in sorted(balances.items())
                    }
                    actual_buckets = {
                        str(k): str(v) for k, v in sorted(payload.get("residual_buckets", {}).items())
                    }
                    if actual_buckets != expected_buckets:
                        return False, index, "residual bucket snapshot mismatch"
                    expected_decision, expected_reason = self.decide_state(state)
                    if payload.get("decision") != expected_decision.value:
                        return False, index, "decision replay mismatch"
                    if payload.get("reason") != expected_reason:
                        return False, index, "reason replay mismatch"
                    expected_offset, expected_tag = self._offset_for(expected_cycle, state)
                    offset = tuple(int(x) for x in payload.get("offset", []))
                    if offset != expected_offset or sum(offset) != 0:
                        return False, index, "neutral offset mismatch"
                    tag = str(payload.get("offset_tag", ""))
                    if tag != expected_tag:
                        return False, index, "offset HMAC mismatch"
                    if tag in seen_tags:
                        return False, index, "repeated offset tag"
                    seen_tags.add(tag)
                else:
                    return False, index, "unknown event type"
            except (ValueError, KeyError, TypeError) as exc:
                return False, index, f"semantic parse failure: {exc}"

        return True, None, "ok"

    def verify_ledger(self) -> Tuple[bool, Optional[int], str]:
        ok, bad, reason = self.verify_hash_chain(self.ledger)
        if not ok:
            return ok, bad, reason
        return self.verify_semantics(self.ledger)

    def export(self) -> Dict[str, Any]:
        with self._lock:
            ledger_copy = copy.deepcopy(self.ledger)
            hash_ok, hash_bad, hash_reason = self.verify_hash_chain(ledger_copy)
            semantic_ok, semantic_bad, semantic_reason = self.verify_semantics(ledger_copy)
            root = ledger_copy[-1]["entry_hash"] if ledger_copy else "0" * 64
            manifest = {
                "schema": "ResidualHonestOperatorRun/2.0",
                "source_sha256": self.source_sha256,
                "residual_unit": self.residual_unit,
                "counter": self.counter,
                "residual_balance": self.residual_balance(),
                "residual_buckets": self.residual_buckets(),
                "ledger_entries": len(ledger_copy),
                "ledger_root": root,
                "hash_chain_valid": hash_ok,
                "hash_chain_bad_index": hash_bad,
                "hash_chain_reason": hash_reason,
                "semantics_valid": semantic_ok,
                "semantics_bad_index": semantic_bad,
                "semantics_reason": semantic_reason,
            }
            manifest_hmac = hmac.new(
                self.hmac_key, canonical_json(manifest).encode("utf-8"), hashlib.sha256
            ).hexdigest()
            return {
                "manifest": json.loads(canonical_json(manifest)),
                "manifest_hmac": manifest_hmac,
                "ledger": ledger_copy,
            }

    def verify_export(self, exported: Mapping[str, Any]) -> Tuple[bool, str]:
        manifest = exported.get("manifest")
        supplied_hmac = str(exported.get("manifest_hmac", ""))
        ledger = exported.get("ledger")
        if not isinstance(manifest, dict) or not isinstance(ledger, list):
            return False, "malformed export envelope"
        expected_hmac = hmac.new(
            self.hmac_key, canonical_json(manifest).encode("utf-8"), hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(supplied_hmac, expected_hmac):
            return False, "manifest HMAC mismatch"
        if manifest.get("source_sha256") != self.source_sha256:
            return False, "source digest mismatch"
        if manifest.get("residual_unit") != self.residual_unit:
            return False, "residual unit mismatch"
        root = ledger[-1]["entry_hash"] if ledger else "0" * 64
        if manifest.get("ledger_root") != root:
            return False, "ledger root mismatch"
        if manifest.get("ledger_entries") != len(ledger):
            return False, "ledger count mismatch"
        hash_ok, _, hash_reason = self.verify_hash_chain(ledger)
        if not hash_ok:
            return False, f"hash chain invalid: {hash_reason}"
        semantic_ok, _, semantic_reason = self.verify_semantics(ledger)
        if not semantic_ok:
            return False, f"semantics invalid: {semantic_reason}"
        return True, "ok"

    def atomic_save(self, path: Path) -> None:
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        payload = canonical_json(self.export()) + "\n"
        fd, temporary = tempfile.mkstemp(prefix=path.name + ".", dir=str(path.parent))
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)


# ---------------------------------------------------------------------------
# Reed–Solomon erasure codec over GF(256)
# ---------------------------------------------------------------------------

_GF_EXP = [0] * 512
_GF_LOG = [0] * 256
_x = 1
for _i in range(255):
    _GF_EXP[_i] = _x
    _GF_LOG[_x] = _i
    _x <<= 1
    if _x & 0x100:
        _x ^= 0x11D
for _i in range(255, 512):
    _GF_EXP[_i] = _GF_EXP[_i - 255]


def gf_mul(a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0
    return _GF_EXP[_GF_LOG[a] + _GF_LOG[b]]


def gf_inv(a: int) -> int:
    if a == 0:
        raise ZeroDivisionError("zero has no multiplicative inverse in GF(256)")
    return _GF_EXP[255 - _GF_LOG[a]]


def gf_pow(a: int, power: int) -> int:
    if power == 0:
        return 1
    if a == 0:
        return 0
    return _GF_EXP[(_GF_LOG[a] * power) % 255]


def matrix_multiply(a: Sequence[Sequence[int]], b: Sequence[Sequence[int]]) -> List[List[int]]:
    rows = len(a)
    shared = len(b)
    cols = len(b[0])
    if any(len(row) != shared for row in a) or any(len(row) != cols for row in b):
        raise ValueError("matrix shape mismatch")
    out = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            value = 0
            for k in range(shared):
                value ^= gf_mul(a[r][k], b[k][c])
            out[r][c] = value
    return out


def matrix_invert(matrix: Sequence[Sequence[int]]) -> List[List[int]]:
    n = len(matrix)
    if n == 0 or any(len(row) != n for row in matrix):
        raise ValueError("matrix must be non-empty and square")
    aug = [list(row) + [1 if r == c else 0 for c in range(n)] for r, row in enumerate(matrix)]
    for col in range(n):
        pivot = next((r for r in range(col, n) if aug[r][col] != 0), None)
        if pivot is None:
            raise ValueError("singular matrix")
        if pivot != col:
            aug[col], aug[pivot] = aug[pivot], aug[col]
        scale = gf_inv(aug[col][col])
        aug[col] = [gf_mul(v, scale) for v in aug[col]]
        for r in range(n):
            if r == col:
                continue
            factor = aug[r][col]
            if factor:
                aug[r] = [x ^ gf_mul(factor, y) for x, y in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def generator_matrix(data_shards: int, parity_shards: int) -> List[List[int]]:
    if data_shards < 1 or parity_shards < 1 or data_shards + parity_shards > 255:
        raise ValueError("invalid Reed–Solomon shard counts")
    n = data_shards + parity_shards
    vandermonde = [
        [gf_pow(row + 1, col) for col in range(data_shards)]
        for row in range(n)
    ]
    top_inverse = matrix_invert(vandermonde[:data_shards])
    return matrix_multiply(vandermonde, top_inverse)


def combine_shards(row: Sequence[int], shards: Sequence[bytes]) -> bytes:
    size = len(shards[0])
    if any(len(shard) != size for shard in shards):
        raise ValueError("shard lengths differ")
    output = bytearray(size)
    for coefficient, shard in zip(row, shards):
        if coefficient == 0:
            continue
        for i, byte in enumerate(shard):
            output[i] ^= gf_mul(coefficient, byte)
    return bytes(output)


def rs_encode(data: bytes, data_shards: int = 4, parity_shards: int = 2) -> Dict[str, Any]:
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes")
    data = bytes(data)
    matrix = generator_matrix(data_shards, parity_shards)
    packet = len(data).to_bytes(8, "big") + data
    shard_size = (len(packet) + data_shards - 1) // data_shards
    packet += b"\x00" * (shard_size * data_shards - len(packet))
    shards = [
        packet[i * shard_size : (i + 1) * shard_size]
        for i in range(data_shards)
    ]
    for row in matrix[data_shards:]:
        shards.append(combine_shards(row, shards[:data_shards]))
    return {
        "schema": "RS-Erasure-Bundle/1.0",
        "data_shards": data_shards,
        "parity_shards": parity_shards,
        "shard_size": shard_size,
        "data_sha256": sha256_hex(data),
        "shards": [
            {
                "index": index,
                "sha256": sha256_hex(shard),
                "data_b64": base64.b64encode(shard).decode("ascii"),
            }
            for index, shard in enumerate(shards)
        ],
    }


def rs_recover(bundle: Mapping[str, Any]) -> Tuple[bool, Optional[bytes], str]:
    try:
        k = int(bundle["data_shards"])
        m = int(bundle["parity_shards"])
        shard_size = int(bundle["shard_size"])
        records = bundle["shards"]
        if not isinstance(records, list) or len(records) != k + m:
            return False, None, "wrong shard count"
        matrix = generator_matrix(k, m)
        shards: List[Optional[bytes]] = [None] * (k + m)
        for expected_index, record in enumerate(records):
            if not isinstance(record, dict) or int(record.get("index", -1)) != expected_index:
                continue
            encoded = record.get("data_b64")
            if encoded is None:
                continue
            try:
                shard = base64.b64decode(encoded, validate=True)
            except Exception:
                continue
            if len(shard) != shard_size:
                continue
            expected_hash = str(record.get("sha256", ""))
            if not hmac.compare_digest(sha256_hex(shard), expected_hash):
                continue
            shards[expected_index] = shard

        present = [i for i, shard in enumerate(shards) if shard is not None]
        missing = (k + m) - len(present)
        if missing > m or len(present) < k:
            return False, None, f"unrecoverable: {missing} shards unavailable/corrupt; parity capacity is {m}"

        selected = present[:k]
        decode_matrix = matrix_invert([matrix[i] for i in selected])
        selected_shards = [shards[i] for i in selected]
        assert all(s is not None for s in selected_shards)
        recovered_data_shards = [
            combine_shards(row, [s for s in selected_shards if s is not None])
            for row in decode_matrix
        ]
        packet = b"".join(recovered_data_shards)
        if len(packet) < 8:
            return False, None, "recovered packet is too short"
        data_length = int.from_bytes(packet[:8], "big")
        if data_length > len(packet) - 8:
            return False, None, "recovered length header is invalid"
        data = packet[8 : 8 + data_length]
        if not hmac.compare_digest(sha256_hex(data), str(bundle.get("data_sha256", ""))):
            return False, None, "recovered data digest mismatch"
        return True, data, "recovered"
    except (KeyError, TypeError, ValueError, ZeroDivisionError) as exc:
        return False, None, f"malformed Reed–Solomon bundle: {exc}"


