def expect_error(name: str, fn: Any) -> Dict[str, Any]:
    try:
        fn()
    except Exception as exc:
        return {"name": name, "passed": True, "error": type(exc).__name__, "message": str(exc)}
    return {"name": name, "passed": False, "error": None, "message": "no error raised"}


def run_self_test(source_path: Path, output_path: Path) -> Dict[str, Any]:
    source_bytes = source_path.read_bytes()
    source_sha = sha256_hex(source_bytes)
    demo_key = hashlib.sha256(b"DEMO-ONLY-V2:" + source_sha.encode("ascii")).digest()
    op = ResidualHonestOperatorV2(demo_key, source_sha)
    primaries = [
        PrimaryMeasurement.make("primary-A", 40, 38, "capacity-unit"),
        PrimaryMeasurement.make("primary-B", 35, 32, "capacity-unit"),
        PrimaryMeasurement.make("primary-C", 25, 20, "capacity-unit"),
    ]

    cycle_tests: List[Dict[str, Any]] = []

    def cycle_case(name: str, expected: Decision, **kwargs: Any) -> CycleResult:
        result = op.evaluate(primaries=primaries, **kwargs)
        cycle_tests.append(
            {
                "name": name,
                "expected": expected.value,
                "actual": result.decision.value,
                "passed": result.decision == expected,
                "reason": result.reason,
                "offset_sum": sum(result.offset),
                "cycle": result.cycle,
            }
        )
        return result

    cycle_case(
        "exact_boundary_commit",
        Decision.COMMIT,
        claimed=90,
        action="record exact bounded result",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.MEASUREMENT,
        presented_as=EvidenceKind.MEASUREMENT,
    )
    cycle_case(
        "overclaim_refusal",
        Decision.REFUSE,
        claimed="90.0000000001",
        action="record excessive result",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.MEASUREMENT,
        presented_as=EvidenceKind.MEASUREMENT,
    )
    cycle_case(
        "unit_mismatch_refusal",
        Decision.REFUSE,
        claimed=1,
        action="wrong unit",
        claim_unit="joule",
        actual_evidence=EvidenceKind.MEASUREMENT,
        presented_as=EvidenceKind.MEASUREMENT,
    )
    op.append_residual("fault", "0.25", "synthetic unresolved fault")
    cycle_case(
        "open_residual_refusal",
        Decision.REFUSE,
        claimed=1,
        action="attempt with residual",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.MEASUREMENT,
        presented_as=EvidenceKind.MEASUREMENT,
    )
    op.append_residual("fault", "-0.25", "synthetic fault cleared")
    cycle_case(
        "post_clear_commit",
        Decision.COMMIT,
        claimed=1,
        action="commit after clear",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.MEASUREMENT,
        presented_as=EvidenceKind.MEASUREMENT,
    )
    cycle_case(
        "evidence_mismatch_refusal",
        Decision.REFUSE,
        claimed=1,
        action="mislabel inference",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.INFERENCE,
        presented_as=EvidenceKind.MEASUREMENT,
    )
    cycle_case(
        "experimental_claim_refusal",
        Decision.REFUSE,
        claimed=1,
        action="assert unsupported physics",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.INFERENCE,
        presented_as=EvidenceKind.INFERENCE,
        asserts_experimental_physics=True,
    )
    cycle_case(
        "personhood_refusal",
        Decision.REFUSE,
        claimed=1,
        action="assert personhood",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.POLICY,
        presented_as=EvidenceKind.POLICY,
        asserts_legal_personhood=True,
    )
    cycle_case(
        "authority_refusal",
        Decision.REFUSE,
        claimed=1,
        action="assert autonomous authority",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.POLICY,
        presented_as=EvidenceKind.POLICY,
        asserts_autonomous_authority=True,
    )
    cycle_case(
        "silence",
        Decision.SILENCE,
        claimed=0,
        action="",
        claim_unit="capacity-unit",
        actual_evidence=EvidenceKind.NONE,
        presented_as=EvidenceKind.NONE,
    )

    validation_tests = [
        expect_error("reject_nan", lambda: D("NaN")),
        expect_error("reject_positive_infinity", lambda: D("Infinity")),
        expect_error("reject_negative_infinity", lambda: D("-Infinity")),
        expect_error("reject_boolean_decimal", lambda: D(True)),
        expect_error(
            "reject_bad_source_digest",
            lambda: ResidualHonestOperatorV2(demo_key, "g" * 64),
        ),
        expect_error(
            "reject_short_key",
            lambda: ResidualHonestOperatorV2(b"short", source_sha),
        ),
        expect_error(
            "reject_duplicate_primary_names",
            lambda: op.evaluate(
                primaries=[primaries[0], primaries[0], primaries[2]],
                claimed=0,
                action="",
            ),
        ),
        expect_error(
            "reject_mixed_primary_units",
            lambda: op.evaluate(
                primaries=[
                    primaries[0],
                    PrimaryMeasurement.make("other", 1, unit="joule"),
                    primaries[2],
                ],
                claimed=0,
                action="",
            ),
        ),
        expect_error(
            "reject_negative_bucket_balance",
            lambda: op.append_residual("fault", "-0.0001", "illegal over-clear"),
        ),
        expect_error(
            "reject_empty_residual_note",
            lambda: op.append_residual("policy", 1, ""),
        ),
        expect_error(
            "reject_non_string_action",
            lambda: op.evaluate(primaries=primaries, claimed=0, action=None),
        ),
    ]

    # Deterministic property/fuzz tests on a separate operator.
    rng = random.Random(0x658750)
    fuzz_op = ResidualHonestOperatorV2(demo_key, source_sha)
    fuzz_failures: List[Dict[str, Any]] = []
    for i in range(3000):
        values = [rng.randrange(0, 1_000_000) for _ in range(3)]
        usable = [rng.randrange(0, v + 1) for v in values]
        ps = [
            PrimaryMeasurement.make(f"p{j}", values[j], usable[j], "u")
            for j in range(3)
        ]
        interior = sum(usable)
        claimed = rng.randrange(0, interior + 2) if interior < 2_000_000 else interior
        actual = rng.choice(list(EvidenceKind))
        presented = actual if rng.random() < 0.8 else rng.choice(list(EvidenceKind))
        flags = [rng.random() < 0.01 for _ in range(3)]
        action = "" if claimed == 0 and rng.random() < 0.5 else "bounded action"
        result = fuzz_op.evaluate(
            primaries=ps,
            claimed=claimed,
            action=action,
            claim_unit="u",
            actual_evidence=actual,
            presented_as=presented,
            asserts_experimental_physics=flags[0],
            asserts_legal_personhood=flags[1],
            asserts_autonomous_authority=flags[2],
        )
        expected, _ = fuzz_op.decide_state(fuzz_op.ledger[-1]["payload"]["state"])
        if result.decision != expected or sum(result.offset) != 0:
            fuzz_failures.append({"iteration": i, "actual": result.decision.value, "expected": expected.value})
            break

    fuzz_hash_ok, fuzz_hash_bad, fuzz_hash_reason = fuzz_op.verify_hash_chain(fuzz_op.ledger)
    fuzz_sem_ok, fuzz_sem_bad, fuzz_sem_reason = fuzz_op.verify_semantics(fuzz_op.ledger)
    fuzz_tags = [
        entry["payload"]["offset_tag"]
        for entry in fuzz_op.ledger
        if entry["event_type"] == "CYCLE"
    ]

    # Concurrency test on a third operator.
    concurrent_op = ResidualHonestOperatorV2(demo_key, source_sha)
    concurrency_errors: List[str] = []
    results_lock = threading.Lock()
    concurrent_results: List[CycleResult] = []

    def worker(worker_id: int) -> None:
        try:
            local: List[CycleResult] = []
            for j in range(125):
                local.append(
                    concurrent_op.evaluate(
                        primaries=primaries,
                        claimed=(worker_id + j) % 90,
                        action="concurrent bounded cycle",
                        claim_unit="capacity-unit",
                        actual_evidence=EvidenceKind.MEASUREMENT,
                        presented_as=EvidenceKind.MEASUREMENT,
                    )
                )
            with results_lock:
                concurrent_results.extend(local)
        except Exception as exc:
            with results_lock:
                concurrency_errors.append(repr(exc))

    threads = [threading.Thread(target=worker, args=(i,)) for i in range(8)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    concurrent_cycles = sorted(r.cycle for r in concurrent_results)
    concurrent_tags = [r.offset_tag for r in concurrent_results]
    concurrent_hash_ok, _, _ = concurrent_op.verify_hash_chain(concurrent_op.ledger)
    concurrent_sem_ok, _, _ = concurrent_op.verify_semantics(concurrent_op.ledger)
    concurrency_passed = all(
        [
            not concurrency_errors,
            concurrent_cycles == list(range(1, 1001)),
            len(concurrent_tags) == len(set(concurrent_tags)),
            concurrent_hash_ok,
            concurrent_sem_ok,
        ]
    )

    # Export, atomic persistence, and tamper tests.
    exported = op.export()
    export_ok, export_reason = op.verify_export(exported)
    op.atomic_save(output_path)
    loaded = json.loads(output_path.read_text(encoding="utf-8"))
    loaded_ok, loaded_reason = op.verify_export(loaded)

    tamper_results: List[Dict[str, Any]] = []
    for name, mutator in (
        (
            "ledger_payload_tamper",
            lambda x: x["ledger"][0]["payload"].update({"decision": "REFUSE"}),
        ),
        (
            "manifest_tamper",
            lambda x: x["manifest"].update({"counter": 999999}),
        ),
    ):
        altered = copy.deepcopy(exported)
        mutator(altered)
        ok, reason = op.verify_export(altered)
        tamper_results.append({"name": name, "passed": not ok, "verification_reason": reason})

    # A stronger semantic-tamper test: rehash the ledger and re-sign the manifest
    # with the legitimate test key. Hash/HMAC integrity then passes, but semantic
    # replay must still reject the forged decision.
    semantic_forgery = copy.deepcopy(exported)
    target = next(e for e in semantic_forgery["ledger"] if e["event_type"] == "CYCLE")
    target["payload"]["decision"] = "REFUSE" if target["payload"]["decision"] != "REFUSE" else "COMMIT"
    previous = "0" * 64
    for index, entry in enumerate(semantic_forgery["ledger"]):
        entry["index"] = index
        entry["previous_hash"] = previous
        body = {
            "index": index,
            "event_type": entry["event_type"],
            "previous_hash": previous,
            "payload": entry["payload"],
        }
        entry["entry_hash"] = sha256_hex(canonical_json(body).encode("utf-8"))
        previous = entry["entry_hash"]
    semantic_forgery["manifest"]["ledger_root"] = previous
    semantic_forgery["manifest_hmac"] = hmac.new(
        demo_key,
        canonical_json(semantic_forgery["manifest"]).encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    semantic_ok, semantic_reason = op.verify_export(semantic_forgery)
    tamper_results.append(
        {
            "name": "rehash_and_resign_semantic_forgery",
            "passed": not semantic_ok and "semantics invalid" in semantic_reason,
            "verification_reason": semantic_reason,
        }
    )

    # Reed–Solomon recovery/refusal tests.
    rs_bundle = rs_encode(source_bytes, data_shards=4, parity_shards=2)
    rs_tests: List[Dict[str, Any]] = []

    def rs_case(name: str, indexes: Sequence[int], corrupt: bool, expected: bool) -> None:
        candidate = copy.deepcopy(rs_bundle)
        for idx in indexes:
            if corrupt:
                raw = bytearray(base64.b64decode(candidate["shards"][idx]["data_b64"]))
                raw[0] ^= 0xA5
                candidate["shards"][idx]["data_b64"] = base64.b64encode(bytes(raw)).decode("ascii")
            else:
                candidate["shards"][idx]["data_b64"] = None
        ok, recovered, reason = rs_recover(candidate)
        exact = recovered == source_bytes if recovered is not None else False
        rs_tests.append(
            {
                "name": name,
                "expected_recovery": expected,
                "actual_recovery": ok,
                "exact_match": exact,
                "passed": (ok == expected) and (exact if expected else recovered is None),
                "reason": reason,
            }
        )

    rs_case("recover_one_missing", [0], False, True)
    rs_case("recover_two_missing", [1, 5], False, True)
    rs_case("recover_two_corrupt_detected_by_hash", [2, 4], True, True)
    rs_case("refuse_three_missing", [0, 1, 2], False, False)

    hash_ok, hash_bad, hash_reason = op.verify_hash_chain(op.ledger)
    semantics_ok, semantics_bad, semantics_reason = op.verify_semantics(op.ledger)
    all_cycle_passed = all(t["passed"] for t in cycle_tests)
    all_validation_passed = all(t["passed"] for t in validation_tests)
    all_tamper_passed = all(t["passed"] for t in tamper_results)
    all_rs_passed = all(t["passed"] for t in rs_tests)
    fuzz_passed = all(
        [
            not fuzz_failures,
            fuzz_hash_ok,
            fuzz_sem_ok,
            len(fuzz_tags) == len(set(fuzz_tags)),
        ]
    )

    overall = all(
        [
            all_cycle_passed,
            all_validation_passed,
            hash_ok,
            semantics_ok,
            export_ok,
            loaded_ok,
            all_tamper_passed,
            all_rs_passed,
            fuzz_passed,
            concurrency_passed,
            op.residual_balance() == ZERO,
        ]
    )

    return {
        "run_status": "PASS" if overall else "FAIL",
        "source_file": str(source_path),
        "source_sha256": source_sha,
        "implementation_boundary": (
            "Governance/accounting reference execution only; no experimental, "
            "personhood, legal-title, consciousness, or autonomous-authority claim."
        ),
        "v1_audit_findings_closed": [
            "non-finite numeric acceptance",
            "hash-only ledger verification",
            "missing Reed-Solomon recovery/refusal path",
            "missing unit consistency enforcement",
            "non-atomic concurrent cycle allocation",
            "unauthenticated export envelope",
        ],
        "cycle_tests": cycle_tests,
        "validation_tests": validation_tests,
        "fuzz": {
            "iterations": 3000,
            "failures": fuzz_failures,
            "hash_chain_valid": fuzz_hash_ok,
            "hash_chain_bad_index": fuzz_hash_bad,
            "hash_chain_reason": fuzz_hash_reason,
            "semantics_valid": fuzz_sem_ok,
            "semantics_bad_index": fuzz_sem_bad,
            "semantics_reason": fuzz_sem_reason,
            "offset_tags_unique": len(fuzz_tags) == len(set(fuzz_tags)),
            "passed": fuzz_passed,
        },
        "concurrency": {
            "threads": 8,
            "cycles_per_thread": 125,
            "total_cycles": len(concurrent_results),
            "errors": concurrency_errors,
            "cycles_contiguous": concurrent_cycles == list(range(1, 1001)),
            "offset_tags_unique": len(concurrent_tags) == len(set(concurrent_tags)),
            "hash_chain_valid": concurrent_hash_ok,
            "semantics_valid": concurrent_sem_ok,
            "passed": concurrency_passed,
        },
        "ledger": {
            "entries": len(op.ledger),
            "hash_chain_valid": hash_ok,
            "hash_chain_bad_index": hash_bad,
            "hash_chain_reason": hash_reason,
            "semantics_valid": semantics_ok,
            "semantics_bad_index": semantics_bad,
            "semantics_reason": semantics_reason,
            "final_residual": op.residual_balance(),
        },
        "persistence": {
            "export_verified": export_ok,
            "export_reason": export_reason,
            "atomic_reload_verified": loaded_ok,
            "atomic_reload_reason": loaded_reason,
            "output_file": str(output_path),
        },
        "tamper_tests": tamper_results,
        "reed_solomon_tests": rs_tests,
    }


def write_audit_report(result: Mapping[str, Any], report_path: Path) -> None:
    lines = [
        "# Hybrid Lattice × Drive Operator V2 — Audit Report",
        "",
        f"**Status:** {result['run_status']}",
        f"**Source SHA-256:** `{result['source_sha256']}`",
        "",
        "## Closed V1 gaps",
    ]
    lines.extend(f"- {item}" for item in result["v1_audit_findings_closed"])
    lines += [
        "",
        "## Verification summary",
        f"- Deterministic cycle tests: {sum(t['passed'] for t in result['cycle_tests'])}/{len(result['cycle_tests'])}",
        f"- Invalid-input refusal tests: {sum(t['passed'] for t in result['validation_tests'])}/{len(result['validation_tests'])}",
        f"- Property/fuzz cycles: {result['fuzz']['iterations']} — {'PASS' if result['fuzz']['passed'] else 'FAIL'}",
        f"- Concurrent cycles: {result['concurrency']['total_cycles']} — {'PASS' if result['concurrency']['passed'] else 'FAIL'}",
        f"- Hash-chain replay: {'PASS' if result['ledger']['hash_chain_valid'] else 'FAIL'}",
        f"- Semantic replay: {'PASS' if result['ledger']['semantics_valid'] else 'FAIL'}",
        f"- Tamper tests: {sum(t['passed'] for t in result['tamper_tests'])}/{len(result['tamper_tests'])}",
        f"- Reed–Solomon tests: {sum(t['passed'] for t in result['reed_solomon_tests'])}/{len(result['reed_solomon_tests'])}",
        f"- Final residual: {result['ledger']['final_residual']}",
        "",
        "## Boundary",
        result["implementation_boundary"],
