#!/usr/bin/env python3
"""Perfected Howard Comma — Lynchpin Merkle Measurements.

Reference implementation for deterministic measurement accounting and
cryptographic provenance. It does not claim experimental validation.
"""
from __future__ import annotations

import hashlib
import json
import math
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any, Iterable, Mapping, Sequence

ZERO = Decimal("0")


def dec(value: Any) -> Decimal:
    try:
        out = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError) as exc:
        raise ValueError(f"invalid decimal: {value!r}") from exc
    if not out.is_finite():
        raise ValueError(f"non-finite decimal: {value!r}")
    return out


def normalize(value: Any) -> Any:
    if isinstance(value, Decimal):
        return format(value, "f")
    if isinstance(value, Mapping):
        return {str(k): normalize(v) for k, v in sorted(value.items(), key=lambda x: str(x[0]))}
    if isinstance(value, (list, tuple)):
        return [normalize(v) for v in value]
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("non-finite float")
        return format(Decimal(str(value)), "f")
    return value


def canonical_json(value: Any) -> bytes:
    return json.dumps(normalize(value), sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def howard_comma(visible_distance: Any, functional_distance: Any, scale: Any) -> Decimal:
    d, dk, lam = dec(visible_distance), dec(functional_distance), dec(scale)
    if d < ZERO or dk < ZERO or lam < ZERO:
        raise ValueError("distances and scale must be non-negative")
    return d - lam * dk


def calibrated_scale(visible: Sequence[Any], functional: Sequence[Any], weights: Sequence[Any] | None = None) -> Decimal:
    if len(visible) != len(functional) or not visible:
        raise ValueError("visible and functional sequences must be non-empty and equal length")
    weights = [1] * len(visible) if weights is None else list(weights)
    if len(weights) != len(visible):
        raise ValueError("weights must match measurement count")
    numerator = ZERO
    denominator = ZERO
    for d0, dk0, w0 in zip(visible, functional, weights):
        d, dk, w = dec(d0), dec(dk0), dec(w0)
        if d < ZERO or dk < ZERO or w < ZERO:
            raise ValueError("distances and weights must be non-negative")
        numerator += w * d * dk
        denominator += w * dk * dk
    if denominator == ZERO:
        raise ValueError("functional-distance denominator is zero")
    return numerator / denominator


def overlap_metrics(overlap_measure: Any, union_measure: Any) -> tuple[Decimal, Decimal]:
    overlap, union = dec(overlap_measure), dec(union_measure)
    if overlap < ZERO or union <= ZERO or overlap > union:
        raise ValueError("require 0 <= overlap <= union and union > 0")
    gamma = overlap / union
    beta = (union - overlap) / union
    if gamma + beta != Decimal("1"):
        raise AssertionError("coherence/residual partition failed")
    return gamma, beta


def leaf_hash(record: Mapping[str, Any]) -> bytes:
    return hashlib.sha256(b"\x00" + canonical_json(record)).digest()


def parent_hash(left: bytes, right: bytes) -> bytes:
    if len(left) != 32 or len(right) != 32:
        raise ValueError("children must be SHA-256 digests")
    return hashlib.sha256(b"\x01" + left + right).digest()


@dataclass(frozen=True)
class ProofStep:
    sibling_hex: str
    sibling_side: str


@dataclass
class MerkleTree:
    records: list[dict[str, Any]]
    levels: list[list[bytes]]

    @classmethod
    def build(cls, records: Iterable[Mapping[str, Any]]) -> "MerkleTree":
        copied = [dict(record) for record in records]
        if not copied:
            raise ValueError("at least one record is required")
        levels = [[leaf_hash(record) for record in copied]]
        while len(levels[-1]) > 1:
            current = levels[-1]
            next_level: list[bytes] = []
            for i in range(0, len(current), 2):
                left = current[i]
                right = current[i + 1] if i + 1 < len(current) else left
                next_level.append(parent_hash(left, right))
            levels.append(next_level)
        return cls(copied, levels)

    @property
    def root_hex(self) -> str:
        return self.levels[-1][0].hex()

    def proof(self, index: int) -> list[ProofStep]:
        if not 0 <= index < len(self.records):
            raise IndexError(index)
        out: list[ProofStep] = []
        cursor = index
        for level in self.levels[:-1]:
            if cursor % 2 == 0:
                j = cursor + 1
                sibling = level[j] if j < len(level) else level[cursor]
                side = "right"
            else:
                sibling = level[cursor - 1]
                side = "left"
            out.append(ProofStep(sibling.hex(), side))
            cursor //= 2
        return out

    @staticmethod
    def verify(record: Mapping[str, Any], proof: Sequence[ProofStep], root_hex: str) -> bool:
        current = leaf_hash(record)
        for step in proof:
            sibling = bytes.fromhex(step.sibling_hex)
            if step.sibling_side == "left":
                current = parent_hash(sibling, current)
            elif step.sibling_side == "right":
                current = parent_hash(current, sibling)
            else:
                return False
        return current.hex() == root_hex


def make_leaf(*, sequence: int, node_id: str, role: str, counterpart: str,
              raw_value: Any, echo_value: Any, visible_distance: Any,
              functional_distance: Any, scale: Any, overlap_measure: Any,
              union_measure: Any, uncertainty: Any, unit: str, counter: int,
              timestamp_utc: str, source_sha256: str,
              prior_commit_sha256: str) -> dict[str, Any]:
    if role not in {"primary", "mirror"}:
        raise ValueError("role must be primary or mirror")
    if not unit:
        raise ValueError("unit is required")
    if dec(uncertainty) < ZERO:
        raise ValueError("uncertainty cannot be negative")
    gamma, beta = overlap_metrics(overlap_measure, union_measure)
    return {
        "schema": "PerfectedHowardCommaLynchpinLeaf/1.0",
        "system": "Lattice-x-Drive-Operator",
        "sequence": sequence,
        "node_id": node_id,
        "role": role,
        "counterpart": counterpart,
        "raw_value": dec(raw_value),
        "echo_value": dec(echo_value),
        "visible_distance": dec(visible_distance),
        "functional_distance": dec(functional_distance),
        "lambda": dec(scale),
        "howard_comma": howard_comma(visible_distance, functional_distance, scale),
        "overlap_measure": dec(overlap_measure),
        "union_measure": dec(union_measure),
        "coherence_gamma": gamma,
        "residual_beta": beta,
        "uncertainty": dec(uncertainty),
        "unit": unit,
        "residual_class": "state_residual",
        "counter": counter,
        "timestamp_utc": timestamp_utc,
        "source_sha256": source_sha256,
        "prior_commit_sha256": prior_commit_sha256,
    }


def run_reference(folder: Path) -> dict[str, Any]:
    commit_text = (folder / "07_VERIFIED_COMMIT_RECORD.txt").read_text(encoding="utf-8")
    payload = commit_text.split("\nHASH\n", 1)[0]
    recomputed = hashlib.sha256(payload.encode("utf-8")).hexdigest()
    declared = commit_text.split("sha256:", 1)[1].splitlines()[0].strip()
    commit_valid = recomputed == declared
    source_sha = hashlib.sha256((folder / "01_SOURCE_SPECIFICATION.md").read_bytes()).hexdigest()

    pairs = [("P1", "E1"), ("P2", "E2"), ("P3", "E3")]
    records: list[dict[str, Any]] = []
    sequence = 0
    for role in ("primary", "mirror"):
        for primary, echo in pairs:
            node, counterpart = (primary, echo) if role == "primary" else (echo, primary)
            records.append(make_leaf(
                sequence=sequence,
                node_id=node,
                role=role,
                counterpart=counterpart,
                raw_value="0.0",
                echo_value="0.0",
                visible_distance="0.0",
                functional_distance="0.0",
                scale="1.0",
                overlap_measure="1.0",
                union_measure="1.0",
                uncertainty="0.0",
                unit="normalized",
                counter=1,
                timestamp_utc="2026-08-06T05:44:10Z",
                source_sha256=source_sha,
                prior_commit_sha256=declared,
            ))
            sequence += 1

    tree = MerkleTree.build(records)
    proofs = []
    for i, record in enumerate(records):
        proof = tree.proof(i)
        proofs.append({
            "index": i,
            "node_id": record["node_id"],
            "leaf_hash": leaf_hash(record).hex(),
            "proof": [step.__dict__ for step in proof],
            "valid": MerkleTree.verify(record, proof, tree.root_hex),
        })

    tampered = dict(records[0])
    tampered["raw_value"] = Decimal("0.1")
    tamper_refused = not MerkleTree.verify(tampered, tree.proof(0), tree.root_hex)
    reordered_root = MerkleTree.build(reversed(records)).root_hex
    ordering_bound = reordered_root != tree.root_hex

    status = "PASS" if all([
        commit_valid,
        all(item["valid"] for item in proofs),
        tamper_refused,
        ordering_bound,
        all(record["howard_comma"] == ZERO for record in records),
        all(record["residual_beta"] == ZERO for record in records),
    ]) else "FAIL"

    return {
        "schema": "PerfectedHowardCommaLynchpinMerkleRun/1.0",
        "status": status,
        "boundary": "Cryptographic commitment and deterministic measurement accounting; not experimental validation.",
        "commit_record": {
            "declared_sha256": declared,
            "recomputed_sha256": recomputed,
            "valid": commit_valid,
        },
        "geometry": {
            "four_thirds_angle_degrees": math.degrees(math.atan2(4, 3)),
            "four_thirds_unit_direction": ["0.6", "0.8"],
            "equal_radius_vesica_angle_degrees": math.degrees(2 * math.acos(0.5)),
            "angles_are_distinct": True,
        },
        "measurement_set": {
            "leaf_count": len(records),
            "complete_48_node_lattice": len(records) == 48,
            "description": "bounded 3-primary + 3-mirror zero-origin commit",
            "records": records,
        },
        "merkle": {
            "algorithm": "SHA-256",
            "leaf_domain_prefix_hex": "00",
            "parent_domain_prefix_hex": "01",
            "root": tree.root_hex,
            "proofs": proofs,
            "all_proofs_valid": all(item["valid"] for item in proofs),
            "tamper_refused": tamper_refused,
            "ordering_bound": ordering_bound,
            "reordered_root": reordered_root,
        },
    }


def main() -> int:
    folder = Path(__file__).resolve().parent
    result = run_reference(folder)
    output = folder / "10_LYNCHPIN_MERKLE_RUN.json"
    output.write_text(json.dumps(normalize(result), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print("PERFECTED HOWARD COMMA — LYNCHPIN MERKLE MEASUREMENTS")
    print(f"Status            : {result['status']}")
    print(f"Commit hash valid : {result['commit_record']['valid']}")
    print(f"Leaves            : {result['measurement_set']['leaf_count']}")
    print(f"Merkle root       : {result['merkle']['root']}")
    print(f"Proofs valid      : {result['merkle']['all_proofs_valid']}")
    print(f"Tamper refused    : {result['merkle']['tamper_refused']}")
    print(f"Ordering bound    : {result['merkle']['ordering_bound']}")
    return 0 if result["status"] == "PASS" else 1


if __name__ == "__main__":
    raise SystemExit(main())

