class EllipticalSpiralOrchestrator {
private:
    double semi_major_axis_a;
    double semi_minor_axis_b;
    double eccentricity;

    double total_angle_theta;        // Unwrapped angle: never resets.
    double expansion_per_revolution; // e.g. 0.15 = +15% per 2π.

    static constexpr double TWO_PI =
        2.0 * std::numbers::pi_v<double>;

public:
    struct SpiralCoordinate {
        std::uint64_t revolution;
        double theta_wrapped;
        double theta_total;
        double expansion_scalar;
        double radius_r;
        double x_coordinate;
        double y_coordinate;
    };

    EllipticalSpiralOrchestrator(
        double a,
        double b,
        double expansion_rate = 0.15
    )
        : semi_major_axis_a(a),
          semi_minor_axis_b(b),
          eccentricity(0.0),
          total_angle_theta(0.0),
          expansion_per_revolution(expansion_rate) {

        if (!std::isfinite(a) || !std::isfinite(b) ||
            a <= 0.0 || b <= 0.0) {
            throw std::invalid_argument(
                "Semi-axes must be finite and positive."
            );
        }

        if (b > a) {
            throw std::invalid_argument(
                "Require semi_major_axis_a >= semi_minor_axis_b."
            );
        }

        if (!std::isfinite(expansion_rate) ||
            expansion_rate < 0.0) {
            throw std::invalid_argument(
                "Expansion rate must be finite and non-negative."
            );
        }

        const double ratio = b / a;
        eccentricity =
            std::sqrt(std::max(0.0, 1.0 - ratio * ratio));
    }

    [[nodiscard]]
    SpiralCoordinate advance_spiral_step(
        double angular_increment =
            std::numbers::pi_v<double> / 4.0
    ) {
        if (!std::isfinite(angular_increment) ||
            angular_increment < 0.0) {
            throw std::invalid_argument(
                "Angular increment must be finite and non-negative."
            );
        }

        // Continuous, monotonic progress coordinate.
        total_angle_theta += angular_increment;

        const auto revolution =
            static_cast<std::uint64_t>(
                std::floor(total_angle_theta / TWO_PI)
            );

        double theta_wrapped =
            std::fmod(total_angle_theta, TWO_PI);

        // Normalize floating-point near-2π residue to zero.
        if (std::abs(theta_wrapped - TWO_PI) < 1e-12 ||
            std::abs(theta_wrapped) < 1e-12) {
            theta_wrapped = 0.0;
        }

        // Continuous scale:
        // +15% after one full 2π turn, but with no boundary jump.
        const double turns =
            total_angle_theta / TWO_PI;

        const double expansion_scalar =
            1.0 + expansion_per_revolution * turns;

        // Focus-polar ellipse:
        // r0(θ) = a(1-e²)/(1-e cos θ)
        const double semi_latus_rectum =
            semi_major_axis_a *
            (1.0 - eccentricity * eccentricity);

        const double denominator =
            1.0 -
            eccentricity * std::cos(theta_wrapped);

        if (denominator <= 0.0) {
            throw std::runtime_error(
                "Invalid ellipse denominator."
            );
        }

        const double base_radius =
            semi_latus_rectum / denominator;

        const double radius =
            base_radius * expansion_scalar;

        const double x =
            radius * std::cos(theta_wrapped);

        const double y =
            radius * std::sin(theta_wrapped);

        return SpiralCoordinate{
            revolution,
            theta_wrapped,
            total_angle_theta,
            expansion_scalar,
            radius,
            x,
            y
        };
    }

    void execute_spiral_trajectory_sequence(int steps) {
        if (steps < 0) {
            throw std::invalid_argument(
                "Step count must be non-negative."
            );
        }

        std::cout
            << "\n--- PHASE FOURTEEN: "
            << "CONTINUOUS ELLIPTICAL SPIRAL OF PROGRESS ---\n";

        std::cout
            << std::fixed
            << std::setprecision(4);

        for (int i = 0; i < steps; ++i) {
            const auto coord =
                advance_spiral_step();

            std::cout
                << "[Spiral] Step " << std::setw(2) << (i + 1)
                << " | Rev " << coord.revolution
                << " | θ=" << coord.theta_wrapped
                << " | Θ=" << coord.theta_total
                << " | Scale=" << coord.expansion_scalar
                << " | r=" << coord.radius_r
                << " | X=" << coord.x_coordinate
                << " | Y=" << coord.y_coordinate
                << '\n';
        }

        std::cout
            << "[Spiral] Continuous trajectory advanced successfully.\n";
    }
};

