    static constexpr double TWO_PI =
        2.0 * std::numbers::pi_v<double>;

    // ------------------------------------------------------------------------
    // Independent interaction calculation — PRIMARY
    //
    // This deliberately produces a bounded normalized interaction weight.
    // It is a computational definition, not a physical law.
    // ------------------------------------------------------------------------
    [[nodiscard]]
    static double primary_interaction_weight(
        const UnitState& left,
        const UnitState& right
    ) {
        const double separation =
            std::abs(left.state_value - right.state_value);

        return 1.0 / (1.0 + separation);
    }

    // ------------------------------------------------------------------------
    // Independent interaction calculation — MIRROR
    //
    // Algebraically equivalent, independently expressed.
    // ------------------------------------------------------------------------
    [[nodiscard]]
    static double mirror_interaction_weight(
        const UnitState& left,
        const UnitState& right
    ) {
        const double hi =
            std::max(left.state_value, right.state_value);

        const double lo =
            std::min(left.state_value, right.state_value);

        const double delta = hi - lo;

        return std::pow(1.0 + delta, -1.0);
    }

    [[nodiscard]]
    static bool approximately_equal(
        double a,
        double b,
        double tolerance
    ) {
        if (!std::isfinite(a) || !std::isfinite(b)) {
            return false;
        }

        const double scale =
            std::max({1.0, std::abs(a), std::abs(b)});

        return std::abs(a - b) <= tolerance * scale;
    }

    [[nodiscard]]
    double wrapped_theta() const {
        double theta =
            std::fmod(total_angle_theta_, TWO_PI);

        if (theta < 0.0) {
            theta += TWO_PI;
        }

        if (std::abs(theta) < 1e-12 ||
            std::abs(theta - TWO_PI) < 1e-12) {
            theta = 0.0;
        }

        return theta;
    }

    [[nodiscard]]
    std::uint64_t current_revolution() const {
        return static_cast<std::uint64_t>(
            std::floor(total_angle_theta_ / TWO_PI)
        );
    }

public:
    InteractionDrivenSpiralOrchestrator(
        double semi_major_axis_a,
        double semi_minor_axis_b,
        double base_angular_increment =
            std::numbers::pi_v<double> / 4.0,
        double expansion_per_revolution = 0.15,
        double mirror_tolerance = 1e-12
    )
        : semi_major_axis_a_(semi_major_axis_a),
          semi_minor_axis_b_(semi_minor_axis_b),
          eccentricity_(0.0),
          total_angle_theta_(0.0),
          retained_consequence_(0.0),
          base_angular_increment_(base_angular_increment),
          expansion_per_revolution_(expansion_per_revolution),
          mirror_tolerance_(mirror_tolerance),
          event_sequence_(0) {

        if (!std::isfinite(semi_major_axis_a_) ||
            !std::isfinite(semi_minor_axis_b_) ||
            semi_major_axis_a_ <= 0.0 ||
            semi_minor_axis_b_ <= 0.0) {
            throw std::invalid_argument(
                "Semi-axes must be finite and positive."
            );
        }

        if (semi_minor_axis_b_ > semi_major_axis_a_) {
            throw std::invalid_argument(
                "Require semi-major axis >= semi-minor axis."
            );
        }

        if (!std::isfinite(base_angular_increment_) ||
            base_angular_increment_ <= 0.0) {
            throw std::invalid_argument(
                "Base angular increment must be finite and positive."
            );
        }

        if (!std::isfinite(expansion_per_revolution_) ||
            expansion_per_revolution_ < 0.0) {
            throw std::invalid_argument(
                "Expansion rate must be finite and non-negative."
            );
        }

        if (!std::isfinite(mirror_tolerance_) ||
            mirror_tolerance_ <= 0.0) {
            throw std::invalid_argument(
                "Mirror tolerance must be finite and positive."
            );
        }

        const double ratio =
            semi_minor_axis_b_ / semi_major_axis_a_;

        eccentricity_ =
            std::sqrt(
                std::max(0.0, 1.0 - ratio * ratio)
            );
    }

    // ========================================================================
    // ★ INTERACTION OPERATOR
    // ========================================================================
    [[nodiscard]]
    CoupledState interact(
        const UnitState& left,
        const UnitState& right
    ) const {
        if (!std::isfinite(left.state_value) ||
            !std::isfinite(right.state_value)) {
            throw std::invalid_argument(
                "Unit state values must be finite."
            );
        }

        const double primary =
            primary_interaction_weight(left, right);

        const double mirror =
            mirror_interaction_weight(left, right);

        if (!approximately_equal(
                primary,
                mirror,
                mirror_tolerance_)) {
            throw std::runtime_error(
                "Mirror mismatch: interaction calculation refused."
            );
        }

        return CoupledState{
            left.id,
            right.id,
            2U,       // 1 ★ 1 = 2
            primary
        };
    }

    // ========================================================================
    // ATOMIC INTERACTION → RETAIN → PROGRESS → COMMIT
    // ========================================================================
    [[nodiscard]]
    SpiralCoordinate process_interaction(
        const UnitState& left,
        const UnitState& right
    ) {
        // S0: compute + mirror verify interaction.
        const CoupledState coupled =
            interact(left, right);

        // Cardinality is independent from interaction magnitude.
        if (coupled.participant_count != 2U) {
            throw std::runtime_error(
                "Interaction cardinality invariant failed."
            );
        }

        const double w =
            coupled.interaction_weight;

        if (!(w > 0.0 && w <= 1.0)) {
            throw std::runtime_error(
                "Interaction weight outside normalized range."
            );
        }

        // --------------------------------------------------------------------
        // PRIMARY progress proposal
        //
        // Every interaction advances the base progress by a fraction w.
        // --------------------------------------------------------------------
        const double primary_delta_theta =
            base_angular_increment_ * w;

        // --------------------------------------------------------------------
        // MIRROR progress proposal
        //
        // Independently reconstructed from the reciprocal interaction scale.
        // Since w = 1/(1+|Δ|):
        //
        //     Δθ = base / (1+|Δ|)
        // --------------------------------------------------------------------
        const double state_delta =
            std::abs(
                left.state_value -
                right.state_value
            );

        const double mirror_delta_theta =
            base_angular_increment_ /
            (1.0 + state_delta);

        const bool mirror_verified =
            approximately_equal(
                primary_delta_theta,
                mirror_delta_theta,
                mirror_tolerance_
            );

        if (!mirror_verified) {
            throw std::runtime_error(
                "Mirror mismatch: progress commit refused."
            );
        }

        // --------------------------------------------------------------------
        // RETAINED CONSEQUENCE
        //
        // M accumulates interaction, while Θ accumulates committed progress.
        // --------------------------------------------------------------------
        const double proposed_retained =
            retained_consequence_ + w;

        const double proposed_theta_total =
            total_angle_theta_ +
            primary_delta_theta;

        // Validate before mutation.
        if (!std::isfinite(proposed_retained) ||
            !std::isfinite(proposed_theta_total)) {
            throw std::runtime_error(
                "Non-finite proposed state: commit refused."
            );
        }

        // --------------------------------------------------------------------
        // ATOMIC COMMIT
        // --------------------------------------------------------------------
        retained_consequence_ =
            proposed_retained;

        total_angle_theta_ =
            proposed_theta_total;

        ++event_sequence_;

        // --------------------------------------------------------------------
        // Geometry projection after commit.
        // --------------------------------------------------------------------
        const double theta =
            wrapped_theta();

        const double turns =
            total_angle_theta_ / TWO_PI;

        const double expansion_scalar =
            1.0 +
            expansion_per_revolution_ * turns;

        const double semi_latus_rectum =
            semi_major_axis_a_ *
            (1.0 - eccentricity_ * eccentricity_);

        const double denominator =
            1.0 -
            eccentricity_ * std::cos(theta);

        if (denominator <= 0.0) {
            throw std::runtime_error(
                "Invalid ellipse denominator."
            );
        }

        const double radius =
            (semi_latus_rectum / denominator) *
            expansion_scalar;

        const double x =
            radius * std::cos(theta);

        const double y =
            radius * std::sin(theta);

        return SpiralCoordinate{
            event_sequence_,
            current_revolution(),
            theta,
            total_angle_theta_,
            retained_consequence_,
            w,
            expansion_scalar,
            radius,
            x,
            y,
            mirror_verified
        };
    }

    void execute_interaction_sequence(
        const std::vector<std::pair<UnitState, UnitState>>& events
    ) {
        std::cout
            << "\n--- PHASE FIFTEEN: "
            << "INTERACTION-DRIVEN ELLIPTICAL SPIRAL ---\n";

        std::cout
            << "Semantic invariant: 1 ★ 1 = 2; "
            << "★ means interaction.\n\n";

        std::cout
            << std::fixed
            << std::setprecision(6);

        for (const auto& event : events) {
            const auto& left =
                event.first;

            const auto& right =
                event.second;

            const auto result =
                process_interaction(
                    left,
                    right
                );

            std::cout
                << "[★] "
                << left.id
                << " ★ "
                << right.id
                << " = 2"
                << " | w=" << result.interaction_weight
                << " | M=" << result.retained_consequence
                << " | Θ=" << result.theta_total
                << " | θ=" << result.theta_wrapped
                << " | Rev=" << result.revolution
                << " | Scale=" << result.expansion_scalar
                << " | r=" << result.radius_r
                << " | X=" << result.x_coordinate
                << " | Y=" << result.y_coordinate
                << " | Mirror="
                << (result.mirror_verified ? "PASS" : "FAIL")
                << '\n';
        }

        std::cout
            << "\n[Commit] All accepted interactions "
            << "advanced retained consequence and progress atomically.\n";
    }
};


