// ============================================================================
// PHASE SIXTEEN
// MERKLE · ECHOES · SHADOWS · REFLECTIONS
//
// Semantic core:
//      1 ★ 1 = 2
//      ★ means INTERACTION.
//
// Distinct mechanisms:
//   REFLECTION : independently recompute the interaction/progress result.
//   SHADOW     : immutable pre-commit projection of the next state.
//   ECHO       : repeated authenticated attestations across 3 lanes × 3 echoes.
//   MERKLE     : SHA-256 tree binding all echo packets + shadow + commit payload.
//
// Commit rule:
//   INTERACT
//      -> REFLECT
//      -> BUILD SHADOW
//      -> 3×3 ECHO
//      -> MERKLE ROOT
//      -> VERIFY
//      -> ATOMIC COMMIT
//
// This is a deterministic computational verification architecture.
// ============================================================================


// ============================================================================
// Minimal SHA-256 implementation
// ============================================================================
class SHA256 {
private:
    std::array<std::uint32_t, 8> state_{
        0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
        0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u
    };

    std::array<std::uint8_t, 64> buffer_{};
    std::uint64_t bit_length_ = 0;
    std::size_t buffer_length_ = 0;

    static constexpr std::array<std::uint32_t, 64> K_{
        0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,
        0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,
        0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,
        0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,
        0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,
        0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,
        0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,
        0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,
        0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,
        0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,
        0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,
        0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,
        0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,
        0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,
        0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,
        0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u
    };

    static std::uint32_t rotr(std::uint32_t x, std::uint32_t n) {
        return (x >> n) | (x << (32u - n));
    }

    void transform(const std::uint8_t* data) {
        std::uint32_t w[64]{};

        for (int i = 0; i < 16; ++i) {
            w[i] =
                (static_cast<std::uint32_t>(data[i*4]) << 24) |
                (static_cast<std::uint32_t>(data[i*4+1]) << 16) |
                (static_cast<std::uint32_t>(data[i*4+2]) << 8) |
                (static_cast<std::uint32_t>(data[i*4+3]));
        }

        for (int i = 16; i < 64; ++i) {
            const std::uint32_t s0 =
                rotr(w[i-15], 7) ^
                rotr(w[i-15], 18) ^
                (w[i-15] >> 3);

            const std::uint32_t s1 =
                rotr(w[i-2], 17) ^
                rotr(w[i-2], 19) ^
                (w[i-2] >> 10);

            w[i] = w[i-16] + s0 + w[i-7] + s1;
        }

        std::uint32_t a = state_[0];
        std::uint32_t b = state_[1];
        std::uint32_t c = state_[2];
        std::uint32_t d = state_[3];
        std::uint32_t e = state_[4];
        std::uint32_t f = state_[5];
        std::uint32_t g = state_[6];
        std::uint32_t h = state_[7];

        for (int i = 0; i < 64; ++i) {
            const std::uint32_t S1 =
                rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            const std::uint32_t ch =
                (e & f) ^ ((~e) & g);
            const std::uint32_t temp1 =
                h + S1 + ch + K_[i] + w[i];

            const std::uint32_t S0 =
                rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            const std::uint32_t maj =
                (a & b) ^ (a & c) ^ (b & c);
            const std::uint32_t temp2 =
                S0 + maj;

            h = g;
            g = f;
            f = e;
            e = d + temp1;
            d = c;
            c = b;
            b = a;
            a = temp1 + temp2;
        }

        state_[0] += a;
        state_[1] += b;
        state_[2] += c;
        state_[3] += d;
        state_[4] += e;
        state_[5] += f;
        state_[6] += g;
        state_[7] += h;
    }

public:
    void update(const std::string& input) {
        update(
            reinterpret_cast<const std::uint8_t*>(input.data()),
            input.size()
        );
    }

    void update(const std::uint8_t* data, std::size_t len) {
        for (std::size_t i = 0; i < len; ++i) {
            buffer_[buffer_length_++] = data[i];
            if (buffer_length_ == 64) {
                transform(buffer_.data());
                bit_length_ += 512;
                buffer_length_ = 0;
            }
        }
    }

    std::string final() {
        std::uint64_t total_bits =
            bit_length_ + static_cast<std::uint64_t>(buffer_length_) * 8u;

        buffer_[buffer_length_++] = 0x80u;

        if (buffer_length_ > 56) {
            while (buffer_length_ < 64) {
                buffer_[buffer_length_++] = 0;
            }
            transform(buffer_.data());
            buffer_length_ = 0;
        }

        while (buffer_length_ < 56) {
            buffer_[buffer_length_++] = 0;
        }

        for (int i = 7; i >= 0; --i) {
            buffer_[buffer_length_++] =
                static_cast<std::uint8_t>((total_bits >> (i * 8)) & 0xffu);
        }

        transform(buffer_.data());

        std::ostringstream oss;
        oss << std::hex << std::setfill('0');

        for (auto v : state_) {
            oss << std::setw(8) << v;
        }

        return oss.str();
    }

    static std::string digest(const std::string& s) {
        SHA256 h;
        h.update(s);
        return h.final();
    }
};


// ============================================================================
// Merkle tree
// ============================================================================
class MerkleTree {
public:
    static std::string root(std::vector<std::string> leaves) {
        if (leaves.empty()) {
            return SHA256::digest("");
        }

        for (auto& leaf : leaves) {
            leaf = SHA256::digest("LEAF|" + leaf);
        }

        while (leaves.size() > 1) {
            if (leaves.size() % 2 != 0) {
                leaves.push_back(leaves.back());
            }

            std::vector<std::string> next;
            next.reserve(leaves.size() / 2);

            for (std::size_t i = 0; i < leaves.size(); i += 2) {
                next.push_back(
                    SHA256::digest(
                        "NODE|" + leaves[i] + "|" + leaves[i+1]
                    )
                );
            }

            leaves = std::move(next);
        }

        return leaves.front();
    }
};


// ============================================================================
// Phase Sixteen engine
// ============================================================================
class MerkleEchoShadowReflectionEngine {
public:
    struct UnitState {
        std::uint64_t id;
        double value;
    };

    struct CoupledState {
        std::uint64_t left_id;
        std::uint64_t right_id;
        std::uint32_t participant_count;
        double interaction_weight;
    };

    struct ShadowState {
        double retained_before;
        double retained_after;
        double theta_before;
        double theta_after;
        double delta_theta;
        double expansion_after;
    };

    struct EchoPacket {
        std::string lane;
        int echo_index;
        std::uint64_t event_sequence;
        std::string parent_hash;
        std::string payload_hash;
        std::string packet_hash;
    };

    struct CommitReceipt {
        std::uint64_t event_sequence;
        bool reflection_pass;
        bool shadow_pass;
        bool echoes_pass;
        bool merkle_pass;

        double interaction_weight;
        double retained_consequence;
        double theta_total;
        double theta_wrapped;
        double radius;
        double x;
        double y;

        std::string echo_merkle_root;
        std::string event_merkle_root;
        std::string commit_hash;
    };

private:
    double a_;
    double b_;
    double eccentricity_;
    double retained_;
    double theta_total_;
    double base_increment_;
    double expansion_rate_;
    double tolerance_;
    std::uint64_t sequence_;

    std::string previous_commit_hash_;

    static constexpr double TWO_PI =
        2.0 * std::numbers::pi_v<double>;

    static std::string canonical_double(double v) {
        std::ostringstream oss;
        oss << std::setprecision(17) << std::scientific << v;
        return oss.str();
    }

    static bool close_enough(double a, double b, double tol) {
        if (!std::isfinite(a) || !std::isfinite(b)) {
            return false;
        }
        const double scale =
            std::max({1.0, std::abs(a), std::abs(b)});
        return std::abs(a - b) <= tol * scale;
    }

    static double primary_weight(
        const UnitState& left,
        const UnitState& right
    ) {
        return 1.0 /
            (1.0 + std::abs(left.value - right.value));
    }

    static double reflected_weight(
        const UnitState& left,
        const UnitState& right
    ) {
        const double hi = std::max(left.value, right.value);
        const double lo = std::min(left.value, right.value);
        const double delta = hi - lo;
        return std::pow(1.0 + delta, -1.0);
    }

    static std::string shadow_payload(
        const ShadowState& s
    ) {
        return
            "shadow|rb=" + canonical_double(s.retained_before) +
            "|ra=" + canonical_double(s.retained_after) +
            "|tb=" + canonical_double(s.theta_before) +
            "|ta=" + canonical_double(s.theta_after) +
            "|dt=" + canonical_double(s.delta_theta) +
            "|ea=" + canonical_double(s.expansion_after);
    }

    static std::string coupled_payload(
        const CoupledState& c
    ) {
        return
            "coupled|left=" + std::to_string(c.left_id) +
            "|right=" + std::to_string(c.right_id) +
            "|count=" + std::to_string(c.participant_count) +
            "|w=" + canonical_double(c.interaction_weight);
    }

    std::vector<EchoPacket> build_echoes(
        const CoupledState& coupled,
        const ShadowState& shadow,
        std::uint64_t event_sequence
    ) const {
        static const std::array<std::string, 3> lanes{
            "SURFACE", "FLOOR", "RESONANT"
        };

        const std::string base_payload =
            coupled_payload(coupled) + "|" + shadow_payload(shadow);

        std::vector<EchoPacket> packets;
        packets.reserve(9);

        for (const auto& lane : lanes) {
            std::string parent =
                SHA256::digest(
                    "LANE_ROOT|" +
                    lane +
                    "|prev_commit=" +
                    previous_commit_hash_
                );

            for (int echo = 0; echo < 3; ++echo) {
                const std::string payload =
                    "lane=" + lane +
                    "|echo=" + std::to_string(echo) +
                    "|seq=" + std::to_string(event_sequence) +
                    "|" + base_payload;

                const std::string payload_hash =
                    SHA256::digest(payload);

                const std::string packet_hash =
                    SHA256::digest(
                        "PACKET|" +
                        parent + "|" +
                        payload_hash
                    );

                packets.push_back(
                    EchoPacket{
                        lane,
                        echo,
                        event_sequence,
                        parent,
                        payload_hash,
                        packet_hash
                    }
                );

                parent = packet_hash;
            }
        }

        return packets;
    }

    bool verify_echoes(
        const std::vector<EchoPacket>& packets,
        const CoupledState& coupled,
        const ShadowState& shadow,
        std::uint64_t event_sequence
    ) const {
        if (packets.size() != 9) {
            return false;
        }

        const auto rebuilt =
            build_echoes(coupled, shadow, event_sequence);

        if (rebuilt.size() != packets.size()) {
            return false;
        }

        for (std::size_t i = 0; i < packets.size(); ++i) {
            if (rebuilt[i].lane != packets[i].lane ||
                rebuilt[i].echo_index != packets[i].echo_index ||
                rebuilt[i].event_sequence != packets[i].event_sequence ||
                rebuilt[i].parent_hash != packets[i].parent_hash ||
                rebuilt[i].payload_hash != packets[i].payload_hash ||
                rebuilt[i].packet_hash != packets[i].packet_hash) {
                return false;
            }
        }

        return true;
    }

public:
    MerkleEchoShadowReflectionEngine(
        double a,
        double b,
        double base_increment =
            std::numbers::pi_v<double> / 4.0,
        double expansion_rate = 0.15,
        double tolerance = 1e-12
    )
        : a_(a),
          b_(b),
          eccentricity_(0.0),
          retained_(0.0),
          theta_total_(0.0),
          base_increment_(base_increment),
          expansion_rate_(expansion_rate),
          tolerance_(tolerance),
          sequence_(0),
          previous_commit_hash_(SHA256::digest("GENESIS")) {

        if (!std::isfinite(a_) || !std::isfinite(b_) ||
            a_ <= 0.0 || b_ <= 0.0 || b_ > a_) {
            throw std::invalid_argument(
                "Require finite positive axes with a >= b."
            );
        }

        const double ratio = b_ / a_;
        eccentricity_ =
            std::sqrt(std::max(0.0, 1.0 - ratio * ratio));
    }

    CommitReceipt process(
        const UnitState& left,
        const UnitState& right
    ) {
        if (!std::isfinite(left.value) ||
            !std::isfinite(right.value)) {
            throw std::invalid_argument(
                "Unit values must be finite."
            );
        }

        // --------------------------------------------------------------------
        // 1) ★ INTERACTION
        // --------------------------------------------------------------------
        const double w_primary =
            primary_weight(left, right);

        const CoupledState coupled{
            left.id,
            right.id,
            2U,
            w_primary
        };

        if (coupled.participant_count != 2U) {
            throw std::runtime_error(
                "1 ★ 1 = 2 cardinality invariant failed."
            );
        }

        // --------------------------------------------------------------------
        // 2) REFLECTION
        // --------------------------------------------------------------------
        const double w_reflected =
            reflected_weight(left, right);

        const double delta_primary =
            base_increment_ * w_primary;

        const double state_delta =
            std::abs(left.value - right.value);

        const double delta_reflected =
            base_increment_ /
            (1.0 + state_delta);

        const bool reflection_pass =
            close_enough(w_primary, w_reflected, tolerance_) &&
            close_enough(delta_primary, delta_reflected, tolerance_);

        if (!reflection_pass) {
            throw std::runtime_error(
                "Reflection mismatch: commit refused."
            );
        }

        // --------------------------------------------------------------------
        // 3) SHADOW
        // --------------------------------------------------------------------
        const double proposed_retained =
            retained_ + w_primary;

        const double proposed_theta =
            theta_total_ + delta_primary;

        const double turns_after =
            proposed_theta / TWO_PI;

        const double expansion_after =
            1.0 + expansion_rate_ * turns_after;

        const ShadowState shadow{
            retained_,
            proposed_retained,
            theta_total_,
            proposed_theta,
            delta_primary,
            expansion_after
        };

        // Independently reconstruct shadow relationships.
        const bool shadow_pass =
            close_enough(
                shadow.retained_before + w_primary,
                shadow.retained_after,
                tolerance_
            ) &&
            close_enough(
                shadow.theta_before + shadow.delta_theta,
                shadow.theta_after,
                tolerance_
            ) &&
            close_enough(
                1.0 +
                    expansion_rate_ *
                    (shadow.theta_after / TWO_PI),
                shadow.expansion_after,
                tolerance_
            );

        if (!shadow_pass) {
            throw std::runtime_error(
                "Shadow reconstruction failed: commit refused."
            );
        }

        // --------------------------------------------------------------------
        // 4) ECHOES — 3 lanes × 3 echoes
        // --------------------------------------------------------------------
        const std::uint64_t next_sequence =
            sequence_ + 1;

        const auto echoes =
            build_echoes(coupled, shadow, next_sequence);

        const bool echoes_pass =
            verify_echoes(
                echoes,
                coupled,
                shadow,
                next_sequence
            );

        if (!echoes_pass) {
            throw std::runtime_error(
                "Echo verification failed: commit refused."
            );
        }

        // --------------------------------------------------------------------
        // 5) MERKLE BINDING
        // --------------------------------------------------------------------
        std::vector<std::string> echo_leaves;
        echo_leaves.reserve(echoes.size());

        for (const auto& e : echoes) {
            echo_leaves.push_back(e.packet_hash);
        }

        const std::string echo_root =
            MerkleTree::root(echo_leaves);

        const std::string shadow_hash =
            SHA256::digest(shadow_payload(shadow));

        const std::string coupled_hash =
            SHA256::digest(coupled_payload(coupled));

        const std::string event_root =
            MerkleTree::root({
                previous_commit_hash_,
                coupled_hash,
                shadow_hash,
                echo_root
            });

        // Rebuild root independently.
        const std::string event_root_check =
            MerkleTree::root({
                previous_commit_hash_,
                SHA256::digest(coupled_payload(coupled)),
                SHA256::digest(shadow_payload(shadow)),
                MerkleTree::root(echo_leaves)
            });

        const bool merkle_pass =
            (event_root == event_root_check);

        if (!merkle_pass) {
            throw std::runtime_error(
                "Merkle root mismatch: commit refused."
            );
        }

        // --------------------------------------------------------------------
        // 6) ATOMIC COMMIT
        // --------------------------------------------------------------------
        retained_ =
            shadow.retained_after;

        theta_total_ =
            shadow.theta_after;

        sequence_ =
            next_sequence;

        double theta_wrapped =
            std::fmod(theta_total_, TWO_PI);

        if (theta_wrapped < 0.0) {
            theta_wrapped += TWO_PI;
        }

        if (std::abs(theta_wrapped) < 1e-12 ||
            std::abs(theta_wrapped - TWO_PI) < 1e-12) {
            theta_wrapped = 0.0;
        }

        const double p =
            a_ * (1.0 - eccentricity_ * eccentricity_);

        const double denominator =
            1.0 - eccentricity_ * std::cos(theta_wrapped);

        if (denominator <= 0.0) {
            throw std::runtime_error(
                "Invalid ellipse denominator."
            );
        }

        const double radius =
            (p / denominator) * shadow.expansion_after;

        const double x =
            radius * std::cos(theta_wrapped);

        const double y =
            radius * std::sin(theta_wrapped);

        const std::string commit_payload =
            "COMMIT|seq=" + std::to_string(sequence_) +
            "|prev=" + previous_commit_hash_ +
            "|event_root=" + event_root +
            "|retained=" + canonical_double(retained_) +
            "|theta=" + canonical_double(theta_total_);

        const std::string commit_hash =
            SHA256::digest(commit_payload);

        previous_commit_hash_ =
            commit_hash;

        return CommitReceipt{
            sequence_,
            reflection_pass,
            shadow_pass,
            echoes_pass,
            merkle_pass,
            w_primary,
            retained_,
            theta_total_,
            theta_wrapped,
            radius,
            x,
            y,
            echo_root,
            event_root,
            commit_hash
        };
    }
};


