// ============================================================================
// PHASE SEVENTEEN
// HARDENED MERKLE · ECHOES · SHADOWS · REFLECTIONS
//
// Semantic invariant:
//      1 ★ 1 = 2
//      ★ means INTERACTION.
//
// Distinct mechanisms:
//   REFLECTION : independent recomputation.
//   SHADOW     : immutable proposed next state.
//   ECHO       : 3 lanes × 3 chained attestations.
//   MERKLE     : SHA-256 binding of the event evidence.
//   COMMIT     : one mutation point, only after every check succeeds.
//
// Hardenings vs Phase Sixteen:
//   1. True two-phase commit: no persistent state mutation before all checks.
//   2. Exact IEEE-754 binary64 serialization for hash canonicalization.
//   3. SHA-256 known-answer self-test ("abc").
//   4. Explicit pre-commit geometry verification.
//   5. Echo/Merkle tamper self-tests.
// ============================================================================


// ============================================================================
// Minimal SHA-256
// ============================================================================
class SHA256 {
private:
    std::array<std::uint32_t, 8> state_{
        0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
        0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u
    };

    std::array<std::uint8_t, 64> buffer_{};
    std::uint64_t bit_length_ = 0;
    std::size_t buffer_length_ = 0;

    static constexpr std::array<std::uint32_t, 64> K_{
        0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,
        0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,
        0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,
        0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,
        0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,
        0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,
        0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,
        0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,
        0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,
        0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,
        0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,
        0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,
        0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,
        0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,
        0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,
        0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u
    };

    static std::uint32_t rotr(std::uint32_t x, std::uint32_t n) {
        return (x >> n) | (x << (32u - n));
    }

    void transform(const std::uint8_t* data) {
        std::uint32_t w[64]{};

        for (int i = 0; i < 16; ++i) {
            w[i] =
                (static_cast<std::uint32_t>(data[i*4]) << 24) |
                (static_cast<std::uint32_t>(data[i*4+1]) << 16) |
                (static_cast<std::uint32_t>(data[i*4+2]) << 8) |
                static_cast<std::uint32_t>(data[i*4+3]);
        }

        for (int i = 16; i < 64; ++i) {
            const std::uint32_t s0 =
                rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >> 3);
            const std::uint32_t s1 =
                rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >> 10);
            w[i] = w[i-16] + s0 + w[i-7] + s1;
        }

        std::uint32_t a = state_[0], b = state_[1], c = state_[2], d = state_[3];
        std::uint32_t e = state_[4], f = state_[5], g = state_[6], h = state_[7];

        for (int i = 0; i < 64; ++i) {
            const std::uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            const std::uint32_t ch = (e & f) ^ ((~e) & g);
            const std::uint32_t t1 = h + S1 + ch + K_[i] + w[i];

            const std::uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            const std::uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            const std::uint32_t t2 = S0 + maj;

            h = g; g = f; f = e; e = d + t1;
            d = c; c = b; b = a; a = t1 + t2;
        }

        state_[0] += a; state_[1] += b; state_[2] += c; state_[3] += d;
        state_[4] += e; state_[5] += f; state_[6] += g; state_[7] += h;
    }

public:
    void update(const std::string& input) {
        update(reinterpret_cast<const std::uint8_t*>(input.data()), input.size());
    }

    void update(const std::uint8_t* data, std::size_t len) {
        for (std::size_t i = 0; i < len; ++i) {
            buffer_[buffer_length_++] = data[i];
            if (buffer_length_ == 64) {
                transform(buffer_.data());
                bit_length_ += 512;
                buffer_length_ = 0;
            }
        }
    }

    std::string final() {
        const std::uint64_t total_bits =
            bit_length_ + static_cast<std::uint64_t>(buffer_length_) * 8u;

        buffer_[buffer_length_++] = 0x80u;

        if (buffer_length_ > 56) {
            while (buffer_length_ < 64) buffer_[buffer_length_++] = 0;
            transform(buffer_.data());
            buffer_length_ = 0;
        }

        while (buffer_length_ < 56) buffer_[buffer_length_++] = 0;

        for (int i = 7; i >= 0; --i) {
            buffer_[buffer_length_++] =
                static_cast<std::uint8_t>((total_bits >> (i * 8)) & 0xffu);
        }

        transform(buffer_.data());

        std::ostringstream oss;
        oss << std::hex << std::setfill('0');
        for (auto v : state_) oss << std::setw(8) << v;
        return oss.str();
    }

    static std::string digest(const std::string& s) {
        SHA256 h;
        h.update(s);
        return h.final();
    }

    static bool self_test() {
        return digest("abc") ==
            "ba7816bf8f01cfea414140de5dae2223"
            "b00361a396177a9cb410ff61f20015ad";
    }
};


// ============================================================================
// Canonical exact scalar representation
// ============================================================================
static std::string canonical_f64(double v) {
    if (!std::isfinite(v)) {
        throw std::invalid_argument("Non-finite binary64 cannot be canonicalized.");
    }

    const std::uint64_t bits = std::bit_cast<std::uint64_t>(v);

    std::ostringstream oss;
    oss << "f64:"
        << std::hex
        << std::setfill('0')
        << std::setw(16)
        << bits;

    return oss.str();
}


// ============================================================================
// Merkle tree
// ============================================================================
class MerkleTree {
public:
    static std::string root(std::vector<std::string> leaves) {
        if (leaves.empty()) {
            return SHA256::digest("EMPTY");
        }

        for (auto& leaf : leaves) {
            leaf = SHA256::digest("LEAF|" + leaf);
        }

        while (leaves.size() > 1) {
            if (leaves.size() & 1u) {
                leaves.push_back(leaves.back());
            }

            std::vector<std::string> next;
            next.reserve(leaves.size() / 2);

            for (std::size_t i = 0; i < leaves.size(); i += 2) {
                next.push_back(
                    SHA256::digest("NODE|" + leaves[i] + "|" + leaves[i+1])
                );
            }

            leaves = std::move(next);
        }

        return leaves.front();
    }
};


// ============================================================================
// Phase Seventeen engine
// ============================================================================
class HardenedInteractionLedger {
public:
    struct UnitState {
        std::uint64_t id;
        double value;
    };

    struct CoupledState {
        std::uint64_t left_id;
        std::uint64_t right_id;
        std::uint32_t participant_count;
        double interaction_weight;
    };

    struct ShadowState {
        double retained_before;
        double retained_after;
        double theta_before;
        double theta_after;
        double delta_theta;
        double expansion_after;

        double radius_after;
        double x_after;
        double y_after;
    };

    struct EchoPacket {
        std::string lane;
        int echo_index;
        std::uint64_t sequence;
        std::string parent_hash;
        std::string payload_hash;
        std::string packet_hash;
    };

    struct Receipt {
        std::uint64_t sequence;
        bool reflection_pass;
        bool shadow_pass;
        bool echoes_pass;
        bool merkle_pass;
        bool atomic_commit_pass;

        double weight;
        double retained;
        double theta_total;
        double theta_wrapped;
        double radius;
        double x;
        double y;

        std::string echo_root;
        std::string event_root;
        std::string commit_hash;
    };

private:
    double a_;
    double b_;
    double e_;
    double retained_ = 0.0;
    double theta_total_ = 0.0;
    double base_increment_;
    double expansion_rate_;
    double tolerance_;
    std::uint64_t sequence_ = 0;

    std::string previous_commit_hash_ = SHA256::digest("GENESIS");

    static constexpr double TWO_PI =
        2.0 * std::numbers::pi_v<double>;

    static bool close_enough(double a, double b, double tol) {
        if (!std::isfinite(a) || !std::isfinite(b)) return false;
        const double scale = std::max({1.0, std::abs(a), std::abs(b)});
        return std::abs(a - b) <= tol * scale;
    }

    static double primary_weight(const UnitState& l, const UnitState& r) {
        return 1.0 / (1.0 + std::abs(l.value - r.value));
    }

    static double reflected_weight(const UnitState& l, const UnitState& r) {
        const double hi = std::max(l.value, r.value);
        const double lo = std::min(l.value, r.value);
        return 1.0 / (1.0 + (hi - lo));
    }

    static std::string coupled_payload(const CoupledState& c) {
        return "coupled"
            "|left=" + std::to_string(c.left_id) +
            "|right=" + std::to_string(c.right_id) +
            "|count=" + std::to_string(c.participant_count) +
            "|w=" + canonical_f64(c.interaction_weight);
    }

    static std::string shadow_payload(const ShadowState& s) {
        return "shadow"
            "|rb=" + canonical_f64(s.retained_before) +
            "|ra=" + canonical_f64(s.retained_after) +
            "|tb=" + canonical_f64(s.theta_before) +
            "|ta=" + canonical_f64(s.theta_after) +
            "|dt=" + canonical_f64(s.delta_theta) +
            "|ea=" + canonical_f64(s.expansion_after) +
            "|r="  + canonical_f64(s.radius_after) +
            "|x="  + canonical_f64(s.x_after) +
            "|y="  + canonical_f64(s.y_after);
    }

    std::vector<EchoPacket> build_echoes(
        const CoupledState& coupled,
        const ShadowState& shadow,
        std::uint64_t seq,
        const std::string& previous_commit
    ) const {
        static const std::array<std::string, 3> lanes{
            "SURFACE", "FLOOR", "RESONANT"
        };

        const std::string common =
            coupled_payload(coupled) + "|" + shadow_payload(shadow);

        std::vector<EchoPacket> packets;
        packets.reserve(9);

        for (const auto& lane : lanes) {
            std::string parent =
                SHA256::digest(
                    "LANE_ROOT|" + lane +
                    "|seq=" + std::to_string(seq) +
                    "|prev=" + previous_commit
                );

            for (int echo = 0; echo < 3; ++echo) {
                const std::string payload =
                    "lane=" + lane +
                    "|echo=" + std::to_string(echo) +
                    "|seq=" + std::to_string(seq) +
                    "|" + common;

                const std::string payload_hash = SHA256::digest(payload);
                const std::string packet_hash =
                    SHA256::digest(
                        "PACKET|" + parent + "|" + payload_hash
                    );

                packets.push_back({
                    lane, echo, seq, parent, payload_hash, packet_hash
                });

                parent = packet_hash;
            }
        }

        return packets;
    }

    bool verify_echoes(
        const std::vector<EchoPacket>& packets,
        const CoupledState& coupled,
        const ShadowState& shadow,
        std::uint64_t seq,
        const std::string& previous_commit
    ) const {
        const auto expected =
            build_echoes(coupled, shadow, seq, previous_commit);

        if (packets.size() != expected.size()) return false;

        for (std::size_t i = 0; i < packets.size(); ++i) {
            if (packets[i].lane != expected[i].lane ||
                packets[i].echo_index != expected[i].echo_index ||
                packets[i].sequence != expected[i].sequence ||
                packets[i].parent_hash != expected[i].parent_hash ||
                packets[i].payload_hash != expected[i].payload_hash ||
                packets[i].packet_hash != expected[i].packet_hash) {
                return false;
            }
        }

        return true;
    }

public:
    HardenedInteractionLedger(
        double a,
        double b,
        double base_increment = std::numbers::pi_v<double> / 4.0,
        double expansion_rate = 0.15,
        double tolerance = 1e-12
    )
        : a_(a),
          b_(b),
          e_(0.0),
          base_increment_(base_increment),
          expansion_rate_(expansion_rate),
          tolerance_(tolerance) {

        if (!SHA256::self_test()) {
            throw std::runtime_error("SHA-256 self-test failed.");
        }

        if (!std::isfinite(a_) || !std::isfinite(b_) ||
            a_ <= 0.0 || b_ <= 0.0 || b_ > a_) {
            throw std::invalid_argument(
                "Require finite positive axes with a >= b."
            );
        }

        if (!std::isfinite(base_increment_) || base_increment_ <= 0.0 ||
            !std::isfinite(expansion_rate_) || expansion_rate_ < 0.0 ||
            !std::isfinite(tolerance_) || tolerance_ <= 0.0) {
            throw std::invalid_argument("Invalid engine parameter.");
        }

        const double ratio = b_ / a_;
        e_ = std::sqrt(std::max(0.0, 1.0 - ratio * ratio));
    }

    Receipt process(const UnitState& left, const UnitState& right) {
        if (!std::isfinite(left.value) || !std::isfinite(right.value)) {
            throw std::invalid_argument("Unit values must be finite.");
        }

        // Capture immutable before-state.
        const double retained_before = retained_;
        const double theta_before = theta_total_;
        const std::uint64_t sequence_before = sequence_;
        const std::string previous_before = previous_commit_hash_;

        // --------------------------------------------------------------------
        // 1) ★ INTERACTION
        // --------------------------------------------------------------------
        const double w_primary = primary_weight(left, right);

        const CoupledState coupled{
            left.id,
            right.id,
            2U,
            w_primary
        };

        if (coupled.participant_count != 2U) {
            throw std::runtime_error("1 ★ 1 = 2 invariant failed.");
        }

        // --------------------------------------------------------------------
        // 2) REFLECTION
        // --------------------------------------------------------------------
        const double w_reflected = reflected_weight(left, right);

        const double delta_primary = base_increment_ * w_primary;
        const double delta_reflected =
            base_increment_ /
            (1.0 + std::abs(left.value - right.value));

        const bool reflection_pass =
            close_enough(w_primary, w_reflected, tolerance_) &&
            close_enough(delta_primary, delta_reflected, tolerance_);

        if (!reflection_pass) {
            throw std::runtime_error("Reflection mismatch.");
        }

        // --------------------------------------------------------------------
        // 3) BUILD COMPLETE SHADOW, INCLUDING GEOMETRY
        // --------------------------------------------------------------------
        const double retained_after = retained_before + w_primary;
        const double theta_after = theta_before + delta_primary;

        double theta_wrapped = std::fmod(theta_after, TWO_PI);
        if (theta_wrapped < 0.0) theta_wrapped += TWO_PI;
        if (std::abs(theta_wrapped) < 1e-12 ||
            std::abs(theta_wrapped - TWO_PI) < 1e-12) {
            theta_wrapped = 0.0;
        }

        const double expansion_after =
            1.0 + expansion_rate_ * (theta_after / TWO_PI);

        const double p =
            a_ * (1.0 - e_ * e_);

        const double denominator =
            1.0 - e_ * std::cos(theta_wrapped);

        if (!(denominator > 0.0) || !std::isfinite(denominator)) {
            throw std::runtime_error("Geometry pre-commit validation failed.");
        }

        const double radius_after =
            (p / denominator) * expansion_after;

        const double x_after =
            radius_after * std::cos(theta_wrapped);

        const double y_after =
            radius_after * std::sin(theta_wrapped);

        const ShadowState shadow{
            retained_before,
            retained_after,
            theta_before,
            theta_after,
            delta_primary,
            expansion_after,
            radius_after,
            x_after,
            y_after
        };

        const bool shadow_pass =
            close_enough(
                shadow.retained_before + w_primary,
                shadow.retained_after,
                tolerance_
            ) &&
            close_enough(
                shadow.theta_before + shadow.delta_theta,
                shadow.theta_after,
                tolerance_
            ) &&
            close_enough(
                1.0 + expansion_rate_ *
                    (shadow.theta_after / TWO_PI),
                shadow.expansion_after,
                tolerance_
            ) &&
            std::isfinite(shadow.radius_after) &&
            std::isfinite(shadow.x_after) &&
            std::isfinite(shadow.y_after);

        if (!shadow_pass) {
            throw std::runtime_error("Shadow reconstruction failed.");
        }

        // --------------------------------------------------------------------
        // 4) ECHOES
        // --------------------------------------------------------------------
        const std::uint64_t next_sequence = sequence_before + 1;

        const auto echoes =
            build_echoes(
                coupled,
                shadow,
                next_sequence,
                previous_before
            );

        const bool echoes_pass =
            verify_echoes(
                echoes,
                coupled,
                shadow,
                next_sequence,
                previous_before
            );

        if (!echoes_pass) {
            throw std::runtime_error("Echo verification failed.");
        }

        // --------------------------------------------------------------------
        // 5) MERKLE
        // --------------------------------------------------------------------
        std::vector<std::string> echo_leaves;
        for (const auto& e : echoes) {
            echo_leaves.push_back(e.packet_hash);
        }

        const std::string echo_root =
            MerkleTree::root(echo_leaves);

        const std::string coupled_hash =
            SHA256::digest(coupled_payload(coupled));

        const std::string shadow_hash =
            SHA256::digest(shadow_payload(shadow));

        const std::string event_root =
            MerkleTree::root({
                previous_before,
                coupled_hash,
                shadow_hash,
                echo_root
            });

        const std::string event_root_check =
            MerkleTree::root({
                previous_before,
                SHA256::digest(coupled_payload(coupled)),
                SHA256::digest(shadow_payload(shadow)),
                MerkleTree::root(echo_leaves)
            });

        const bool merkle_pass =
            event_root == event_root_check;

        if (!merkle_pass) {
            throw std::runtime_error("Merkle verification failed.");
        }

        // --------------------------------------------------------------------
        // 6) PRECOMPUTE COMMIT HASH — STILL NO MUTATION
        // --------------------------------------------------------------------
        const std::string commit_payload =
            "COMMIT"
            "|seq=" + std::to_string(next_sequence) +
            "|prev=" + previous_before +
            "|event_root=" + event_root +
            "|retained=" + canonical_f64(retained_after) +
            "|theta=" + canonical_f64(theta_after) +
            "|radius=" + canonical_f64(radius_after) +
            "|x=" + canonical_f64(x_after) +
            "|y=" + canonical_f64(y_after);

        const std::string commit_hash =
            SHA256::digest(commit_payload);

        // --------------------------------------------------------------------
        // 7) ATOMIC COMMIT — ONLY MUTATION POINT
        // --------------------------------------------------------------------
        retained_ = retained_after;
        theta_total_ = theta_after;
        sequence_ = next_sequence;
        previous_commit_hash_ = commit_hash;

        const bool atomic_commit_pass =
            close_enough(retained_, retained_after, tolerance_) &&
            close_enough(theta_total_, theta_after, tolerance_) &&
            sequence_ == next_sequence &&
            previous_commit_hash_ == commit_hash;

        if (!atomic_commit_pass) {
            throw std::runtime_error("Atomic commit verification failed.");
        }

        return Receipt{
            sequence_,
            reflection_pass,
            shadow_pass,
            echoes_pass,
            merkle_pass,
            atomic_commit_pass,
            w_primary,
            retained_,
            theta_total_,
            theta_wrapped,
            radius_after,
            x_after,
            y_after,
            echo_root,
            event_root,
            commit_hash
        };
    }

    // Adversarial unit test proving one changed packet breaks verification.
    bool tamper_test() const {
        const UnitState l{100, 1.0};
        const UnitState r{101, 1.25};

        const double w = primary_weight(l, r);
        const CoupledState c{l.id, r.id, 2U, w};

        const double dt = base_increment_ * w;
        const double ta = theta_total_ + dt;
        const double ra = retained_ + w;
        const double ex = 1.0 + expansion_rate_ * (ta / TWO_PI);

        double tw = std::fmod(ta, TWO_PI);
        if (tw < 0) tw += TWO_PI;

        const double p = a_ * (1.0 - e_ * e_);
        const double den = 1.0 - e_ * std::cos(tw);
        const double rad = (p / den) * ex;

        const ShadowState s{
            retained_, ra, theta_total_, ta, dt, ex,
            rad, rad * std::cos(tw), rad * std::sin(tw)
        };

        auto packets =
            build_echoes(c, s, sequence_ + 1, previous_commit_hash_);

        if (packets.empty()) return false;

        packets[4].packet_hash[0] =
            (packets[4].packet_hash[0] == '0') ? '1' : '0';

        return !verify_echoes(
            packets, c, s, sequence_ + 1, previous_commit_hash_
        );
    }
};


