// ============================================================================
// SHA-256
// ============================================================================
class SHA256 {
private:
    std::array<std::uint32_t, 8> state_{
        0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
        0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u
    };
    std::array<std::uint8_t, 64> buffer_{};
    std::uint64_t bit_length_ = 0;
    std::size_t buffer_length_ = 0;


    static constexpr std::array<std::uint32_t, 64> K_{
        0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,
        0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,
        0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,
        0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,
        0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,
        0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,
        0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,
        0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,
        0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,
        0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,
        0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,
        0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,
        0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,
        0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,
        0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,
        0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u
    };


    static std::uint32_t rotr(std::uint32_t x, std::uint32_t n) {
        return (x >> n) | (x << (32u - n));
    }


    void transform(const std::uint8_t* data) {
        std::uint32_t w[64]{};
        for (int i = 0; i < 16; ++i) {
            w[i] =
                (static_cast<std::uint32_t>(data[i*4]) << 24) |
                (static_cast<std::uint32_t>(data[i*4+1]) << 16) |
                (static_cast<std::uint32_t>(data[i*4+2]) << 8) |
                static_cast<std::uint32_t>(data[i*4+3]);
        }
        for (int i = 16; i < 64; ++i) {
            const auto s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15] >> 3);
            const auto s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2] >> 10);
            w[i] = w[i-16] + s0 + w[i-7] + s1;
        }


        auto a=state_[0], b=state_[1], c=state_[2], d=state_[3];
        auto e=state_[4], f=state_[5], g=state_[6], h=state_[7];


        for (int i=0;i<64;++i) {
            const auto S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
            const auto ch = (e&f)^((~e)&g);
            const auto t1 = h+S1+ch+K_[i]+w[i];
            const auto S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
            const auto maj = (a&b)^(a&c)^(b&c);
            const auto t2 = S0+maj;
            h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
        }


        state_[0]+=a; state_[1]+=b; state_[2]+=c; state_[3]+=d;
        state_[4]+=e; state_[5]+=f; state_[6]+=g; state_[7]+=h;
    }


public:
    void update(const std::uint8_t* data, std::size_t len) {
        for (std::size_t i=0;i<len;++i) {
            buffer_[buffer_length_++] = data[i];
            if (buffer_length_ == 64) {
                transform(buffer_.data());
                bit_length_ += 512;
                buffer_length_ = 0;
            }
        }
    }
    void update(std::string_view s) {
        update(reinterpret_cast<const std::uint8_t*>(s.data()), s.size());
    }
    std::array<std::uint8_t,32> final_bytes() {
        const std::uint64_t total_bits =
            bit_length_ + static_cast<std::uint64_t>(buffer_length_) * 8u;


        buffer_[buffer_length_++] = 0x80u;
        if (buffer_length_ > 56) {
            while (buffer_length_ < 64) buffer_[buffer_length_++] = 0;
            transform(buffer_.data());
            buffer_length_ = 0;
        }
        while (buffer_length_ < 56) buffer_[buffer_length_++] = 0;
        for (int i=7;i>=0;--i) {
            buffer_[buffer_length_++] =
                static_cast<std::uint8_t>((total_bits >> (i*8)) & 0xffu);
        }
        transform(buffer_.data());


        std::array<std::uint8_t,32> out{};
        for (std::size_t i=0;i<8;++i) {
            out[i*4+0] = static_cast<std::uint8_t>(state_[i] >> 24);
            out[i*4+1] = static_cast<std::uint8_t>(state_[i] >> 16);
            out[i*4+2] = static_cast<std::uint8_t>(state_[i] >> 8);
            out[i*4+3] = static_cast<std::uint8_t>(state_[i]);
        }
        return out;
    }
    static std::string hex(const std::array<std::uint8_t,32>& b) {
        std::ostringstream oss;
        oss << std::hex << std::setfill('0');
        for (auto v : b) oss << std::setw(2) << static_cast<unsigned>(v);
        return oss.str();
    }
    static std::string digest(std::string_view s) {
        SHA256 h;
        h.update(s);
        return hex(h.final_bytes());
    }
    static bool self_test() {
        return digest("abc") ==
          "ba7816bf8f01cfea414140de5dae2223"
          "b00361a396177a9cb410ff61f20015ad";
    }
};




// ============================================================================
// HMAC-SHA256
// ============================================================================
static std::string hmac_sha256(
    const std::string& key,
    const std::string& message
) {
    constexpr std::size_t BLOCK = 64;


    std::array<std::uint8_t, BLOCK> k0{};
    if (key.size() > BLOCK) {
        SHA256 kh;
        kh.update(reinterpret_cast<const std::uint8_t*>(key.data()), key.size());
        const auto dig = kh.final_bytes();
        std::copy(dig.begin(), dig.end(), k0.begin());
    } else {
        std::copy(key.begin(), key.end(), k0.begin());
    }


    std::array<std::uint8_t, BLOCK> ipad{}, opad{};
    for (std::size_t i=0;i<BLOCK;++i) {
        ipad[i] = static_cast<std::uint8_t>(k0[i] ^ 0x36u);
        opad[i] = static_cast<std::uint8_t>(k0[i] ^ 0x5cu);
    }


    SHA256 inner;
    inner.update(ipad.data(), ipad.size());
    inner.update(reinterpret_cast<const std::uint8_t*>(message.data()), message.size());
    const auto inner_digest = inner.final_bytes();


    SHA256 outer;
    outer.update(opad.data(), opad.size());
    outer.update(inner_digest.data(), inner_digest.size());
    return SHA256::hex(outer.final_bytes());
}




// ============================================================================
