using u64 = std::uint64_t;
using u128 = unsigned __int128;


static constexpr u64 SCALE = 1'000'000'000ULL; // 1e9 fixed-point
static constexpr u64 BASE_INCREMENT = 785'398'163ULL; // ~pi/4 in nanoradian units


static u64 checked_add(u64 a, u64 b, const char* what) {
    if (b > std::numeric_limits<u64>::max() - a) {
        throw std::overflow_error(std::string("overflow: ") + what);
    }
    return a + b;
}


static u64 abs_diff(u64 a, u64 b) {
    return a >= b ? a-b : b-a;
}


// w = 1 / (1 + |x-y|), represented at SCALE.
// x/y are also SCALE-based fixed-point.
static u64 interaction_weight_q(u64 x_q, u64 y_q) {
    const u64 delta = abs_diff(x_q, y_q);
    const u64 denominator = checked_add(SCALE, delta, "interaction denominator");
    const u128 numerator = static_cast<u128>(SCALE) * static_cast<u128>(SCALE);
    return static_cast<u64>(numerator / denominator);
}


static u64 mul_scaled(u64 a_q, u64 b_q) {
    const u128 p = static_cast<u128>(a_q) * static_cast<u128>(b_q);
    const u128 q = p / SCALE;
    if (q > std::numeric_limits<u64>::max()) {
        throw std::overflow_error("scaled multiply overflow");
    }
    return static_cast<u64>(q);
}




