static std::vector<std::string> split(const std::string& s, char d) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : s) {
        if (c == d) { out.push_back(cur); cur.clear(); }
        else cur.push_back(c);
    }
    out.push_back(cur);
    return out;
}


static u64 parse_u64(const std::string& s) {
    std::size_t idx = 0;
    unsigned long long v = std::stoull(s, &idx, 10);
    if (idx != s.size()) throw std::runtime_error("invalid integer field");
    return static_cast<u64>(v);
}


static JournalRecord parse_record(const std::string& line) {
    const auto f = split(line, '|');
    if (f.size() != 14) {
        throw std::runtime_error("journal field count mismatch");
    }
    return JournalRecord{
        parse_u64(f[0]),
        parse_u64(f[1]),
        parse_u64(f[2]),
        parse_u64(f[3]),
        parse_u64(f[4]),
        parse_u64(f[5]),
        parse_u64(f[6]),
        parse_u64(f[7]),
        f[8], f[9], f[10], f[11], f[12], f[13]
    };
}




// ============================================================================
// Durable append helper
// ============================================================================
static void durable_append_line(const std::string& path, const std::string& line) {
    const int fd = ::open(path.c_str(), O_CREAT | O_WRONLY | O_APPEND, 0600);
    if (fd < 0) {
        throw std::runtime_error(
            "open journal failed: " + std::string(std::strerror(errno))
        );
    }


    const std::string data = line + "\n";
    std::size_t written = 0;


    while (written < data.size()) {
        const ssize_t n = ::write(
            fd,
            data.data() + written,
            data.size() - written
        );
        if (n < 0) {
            const auto msg = std::string(std::strerror(errno));
            ::close(fd);
            throw std::runtime_error("write journal failed: " + msg);
        }
        written += static_cast<std::size_t>(n);
    }


    if (::fsync(fd) != 0) {
        const auto msg = std::string(std::strerror(errno));
        ::close(fd);
        throw std::runtime_error("fsync journal failed: " + msg);
    }


    if (::close(fd) != 0) {
        throw std::runtime_error("close journal failed");
    }
}




// ============================================================================
// Phase Eighteen ledger
// ============================================================================
class DurableAuthenticatedInteractionLedger {
public:
    struct UnitState {
        u64 id{};
        u64 value_q{}; // SCALE-based fixed-point
    };


    struct Receipt {
        u64 sequence{};
        u64 weight_q{};
        u64 retained_q{};
        u64 theta_q{};
        std::string previous_hash;
        std::string event_root;
        std::string commit_hash;
    };


private:
    mutable std::mutex mutex_;
    std::string journal_path_;


    // Lane secrets are supplied externally to constructor.
    std::string key_surface_;
    std::string key_floor_;
    std::string key_resonant_;


    u64 sequence_ = 0;
    u64 retained_q_ = 0;
    u64 theta_q_ = 0;
    std::string head_hash_ = SHA256::digest("GENESIS|PHASE18");


    bool verify_record(
        const JournalRecord& r,
        u64 expected_seq,
        u64 retained_before,
        u64 theta_before,
        const std::string& expected_prev
    ) const {
        if (r.seq != expected_seq) return false;
        if (r.previous_hash != expected_prev) return false;


        const u64 expected_w = interaction_weight_q(r.left_q, r.right_q);
        if (r.weight_q != expected_w) return false;


        const u64 expected_retained =
            checked_add(retained_before, expected_w, "recovery retained");
        if (r.retained_q != expected_retained) return false;


        const u64 delta_theta =
            mul_scaled(BASE_INCREMENT, expected_w);
        const u64 expected_theta =
            checked_add(theta_before, delta_theta, "recovery theta");
        if (r.theta_q != expected_theta) return false;


        const std::string payload = core_payload(
            r.seq, r.left_id, r.right_id,
            r.left_q, r.right_q, r.weight_q,
            r.retained_q, r.theta_q, r.previous_hash
        );
        const std::string core_hash = SHA256::digest(payload);


        const std::string s = hmac_sha256(key_surface_,  "SURFACE|"  + payload);
        const std::string f = hmac_sha256(key_floor_,    "FLOOR|"    + payload);
        const std::string z = hmac_sha256(key_resonant_, "RESONANT|" + payload);


        if (r.surface_mac != s ||
            r.floor_mac != f ||
            r.resonant_mac != z) {
            return false;
        }


        const std::string er = event_root_for(core_hash, s, f, z);
        if (r.event_root != er) return false;


        const std::string ch =
            commit_hash_for(r.seq, r.previous_hash, r.event_root);
        return r.commit_hash == ch;
    }


    void recover() {
        std::ifstream in(journal_path_);
        if (!in.good()) {
            return; // no journal yet = genesis
        }


        u64 seq = 0;
        u64 retained = 0;
        u64 theta = 0;
        std::string head = SHA256::digest("GENESIS|PHASE18");


        std::string line;
        while (std::getline(in, line)) {
            if (line.empty()) continue;
            const JournalRecord r = parse_record(line);


            const u64 next_seq =
                checked_add(seq, 1, "recovery sequence");


            if (!verify_record(r, next_seq, retained, theta, head)) {
                throw std::runtime_error(
                    "journal verification failed at seq " +
                    std::to_string(next_seq)
                );
            }


            seq = r.seq;
            retained = r.retained_q;
            theta = r.theta_q;
            head = r.commit_hash;
        }


        sequence_ = seq;
        retained_q_ = retained;
        theta_q_ = theta;
        head_hash_ = head;
    }


public:
    DurableAuthenticatedInteractionLedger(
        std::string journal_path,
        std::string key_surface,
        std::string key_floor,
        std::string key_resonant
    )
        : journal_path_(std::move(journal_path)),
          key_surface_(std::move(key_surface)),
          key_floor_(std::move(key_floor)),
          key_resonant_(std::move(key_resonant)) {


        if (!SHA256::self_test()) {
            throw std::runtime_error("SHA-256 self-test failed");
        }


        if (key_surface_.empty() ||
            key_floor_.empty() ||
            key_resonant_.empty()) {
            throw std::invalid_argument("echo lane keys must be non-empty");
        }


        if (key_surface_ == key_floor_ ||
            key_surface_ == key_resonant_ ||
            key_floor_ == key_resonant_) {
            throw std::invalid_argument(
                "echo lane keys must be distinct"
            );
        }


        recover();
    }


    [[nodiscard]]
    std::string head_hash() const {
        std::scoped_lock lock(mutex_);
        return head_hash_;
    }


    [[nodiscard]]
    u64 sequence() const {
        std::scoped_lock lock(mutex_);
        return sequence_;
    }


    Receipt process(
        const UnitState& left,
        const UnitState& right,
        const std::optional<std::string>& expected_parent = std::nullopt
    ) {
        std::scoped_lock lock(mutex_);


        // CAS-style stale-parent / fork rejection.
        if (expected_parent && *expected_parent != head_hash_) {
            throw std::runtime_error("STALE_PARENT_OR_FORK");
        }


        const u64 next_seq =
            checked_add(sequence_, 1, "sequence");


        const u64 w =
            interaction_weight_q(left.value_q, right.value_q);


        const u64 next_retained =
            checked_add(retained_q_, w, "retained");


        const u64 delta_theta =
            mul_scaled(BASE_INCREMENT, w);


        const u64 next_theta =
            checked_add(theta_q_, delta_theta, "theta");


        const std::string previous = head_hash_;


        const std::string payload = core_payload(
            next_seq,
            left.id,
            right.id,
            left.value_q,
            right.value_q,
            w,
            next_retained,
            next_theta,
            previous
        );


        const std::string core_hash =
            SHA256::digest(payload);


        const std::string surface_mac =
            hmac_sha256(key_surface_, "SURFACE|" + payload);
        const std::string floor_mac =
            hmac_sha256(key_floor_, "FLOOR|" + payload);
        const std::string resonant_mac =
            hmac_sha256(key_resonant_, "RESONANT|" + payload);


        const std::string event_root =
            event_root_for(
                core_hash,
                surface_mac,
                floor_mac,
                resonant_mac
            );


        const std::string commit_hash =
            commit_hash_for(
                next_seq,
                previous,
                event_root
            );


        const JournalRecord record{
            next_seq,
            left.id,
            right.id,
            left.value_q,
            right.value_q,
            w,
            next_retained,
            next_theta,
            previous,
            surface_mac,
            floor_mac,
            resonant_mac,
            event_root,
            commit_hash
        };


        // DURABLE COMMIT ORDER:
        // 1. Entire record derived.
        // 2. Append + fsync succeeds.
        // 3. Only then move authoritative in-memory head.
        durable_append_line(
            journal_path_,
            serialize_record(record)
        );


        sequence_ = next_seq;
        retained_q_ = next_retained;
        theta_q_ = next_theta;
        head_hash_ = commit_hash;


        return Receipt{
            sequence_,
            w,
            retained_q_,
            theta_q_,
            previous,
            event_root,
            commit_hash
        };
    }
};




// ============================================================================
// Demonstration / self-audit
// ============================================================================
int main() {
    try {
        const std::string journal =
            "/tmp/phase18_interaction_ledger.journal";


        // Start clean for deterministic demo only.
        ::unlink(journal.c_str());


        const std::string ks = "phase18-demo-surface-key";
        const std::string kf = "phase18-demo-floor-key";
        const std::string kr = "phase18-demo-resonant-key";


        using Engine = DurableAuthenticatedInteractionLedger;


        Engine engine(journal, ks, kf, kr);


        std::cout
            << "\n=== PHASE EIGHTEEN ===\n"
            << "DURABLE · AUTHENTICATED · SINGLE-WRITER INTERACTION LEDGER\n"
            << "1 ★ 1 = 2; ★ = INTERACTION\n"
            << "SHA-256 KAT: "
            << (SHA256::self_test() ? "PASS" : "FAIL")
            << "\n\n";


        const std::vector<std::pair<Engine::UnitState, Engine::UnitState>> events{
            {{1, 1'000'000'000ULL}, {1, 1'000'000'000ULL}},
            {{1, 1'000'000'000ULL}, {2, 1'250'000'000ULL}},
            {{2, 1'250'000'000ULL}, {3, 1'750'000'000ULL}},
            {{3, 1'750'000'000ULL}, {4, 1'800'000'000ULL}}
        };


        std::string first_parent;


        for (std::size_t i=0;i<events.size();++i) {
            const std::string parent = engine.head_hash();
            if (i == 0) first_parent = parent;


            const auto r = engine.process(
                events[i].first,
                events[i].second,
                parent
            );


            std::cout
                << "[★] "
                << events[i].first.id
                << " ★ "
                << events[i].second.id
                << " = 2"
                << " | seq=" << r.sequence
                << " | weight_q=" << r.weight_q
                << " | retained_q=" << r.retained_q
                << " | theta_q=" << r.theta_q
                << "\n"
                << "    EventRoot: " << r.event_root << "\n"
                << "    Commit   : " << r.commit_hash << "\n\n";
        }


        const std::string terminal_head = engine.head_hash();
        const u64 terminal_seq = engine.sequence();


        // Recovery test: new instance must reconstruct same head.
        Engine recovered(journal, ks, kf, kr);


        const bool recovery_pass =
            recovered.head_hash() == terminal_head &&
            recovered.sequence() == terminal_seq;


        // Stale-parent/fork test.
        bool fork_rejected = false;
        try {
            recovered.process(
                {99, 1'000'000'000ULL},
                {100, 1'000'000'000ULL},
                first_parent
            );
        } catch (const std::exception& e) {
            fork_rejected =
                std::string(e.what()) == "STALE_PARENT_OR_FORK";
        }


        // Journal tamper test on a copied file.
        const std::string tampered =
            "/tmp/phase18_interaction_ledger_tampered.journal";
        {
            std::ifstream in(journal, std::ios::binary);
            std::ofstream out(tampered, std::ios::binary | std::ios::trunc);
            out << in.rdbuf();
        }
        {
            std::fstream f(
                tampered,
                std::ios::in | std::ios::out | std::ios::binary
            );
            char c = 0;
            f.seekg(10);
            f.get(c);
            f.seekp(10);
            f.put(c == '0' ? '1' : '0');
        }


        bool tamper_rejected = false;
        try {
            Engine bad(tampered, ks, kf, kr);
        } catch (...) {
            tamper_rejected = true;
        }


        std::cout
            << "Recovery verification : "
            << (recovery_pass ? "PASS" : "FAIL") << "\n"
            << "Stale-parent rejection: "
            << (fork_rejected ? "PASS" : "FAIL") << "\n"
            << "Journal tamper reject : "
            << (tamper_rejected ? "PASS" : "FAIL") << "\n"
            << "Terminal sequence      : "
            << terminal_seq << "\n"
            << "Terminal head          : "
            << terminal_head << "\n";


        return (
            recovery_pass &&
            fork_rejected &&
            tamper_rejected
        ) ? 0 : 2;
    }
    catch (const std::exception& ex) {
        std::cerr << "ERROR: " << ex.what() << '\n';
        return 1;
    }
}
